function hpAdaptiveMobileHomeState(d,readiness){
  const response=d?.respostaSessao||{};
  const sessionToday=!!response.sessaoInicioUtc && String(response.sessaoInicioUtc).slice(0,10)===todayISO();
  const closed=!!d?.execucaoDoDia?.diaFechado;
  if(closed)return {stage:'closed',tone:'calm',eyebrow:'DIA CONCLUÍDO',title:'Seu dia já está fechado',copy:'O que precisava ser registrado hoje está salvo. Agora o app reduz o ruído e deixa recuperação em primeiro plano.'};
  if(sessionToday)return {stage:'recovery',tone:'recover',eyebrow:'PÓS-TREINO',title:'Agora é hora de observar a resposta',copy:'A sessão já aconteceu. Priorize recuperação, hidratação e fechamento do dia sem transformar sinais isolados em diagnóstico.'};
  if(readiness)return {stage:'training',tone:'active',eyebrow:'CONTEXTO ATUALIZADO',title:'Prontidão registrada',copy:'Seu contexto do dia já está disponível. O próximo passo é seguir o plano de treino definido para hoje.'};
  return {stage:'checkin',tone:'start',eyebrow:'COMECE POR AQUI',title:'Atualize como seu corpo acordou',copy:'Um check-in curto organiza prontidão, treino e recuperação antes de qualquer outra decisão do dia.'};
}

function hpAdaptiveMobileHomeCue(state){
  if(!state)return '';
  return `<section class="adaptive-day-cue ${state.tone}" aria-label="Prioridade atual do seu dia" data-adaptive-stage="${state.stage}">
    <div><span class="eyebrow">${esc(state.eyebrow)}</span><h3>${esc(state.title)}</h3><p>${esc(state.copy)}</p></div>
    <span class="adaptive-day-stage" aria-hidden="true">${state.stage==='closed'?'✓':state.stage==='recovery'?'♻':state.stage==='training'?'↗':'◉'}</span>
  </section>`;
}

function hpDailyAthleteTimeline(d,readiness){
  const response=d?.respostaSessao||{};
  const sessionToday=!!response.sessaoInicioUtc && String(response.sessaoInicioUtc).slice(0,10)===todayISO();
  const responseReady=!!response.dataCheckInResposta;
  const checkState=readiness?'done':'current';
  const workoutState=sessionToday?'done':readiness?'current':'upcoming';
  const recoveryState=responseReady?'done':sessionToday?'current':'upcoming';
  const workoutText=sessionToday?'Sessão concluída':readiness?'Treino do dia':'Depois do check-in';
  const recoveryText=responseReady?'Resposta registrada':sessionToday?'Acompanhar recuperação':'Após o treino';
  return `<section class="athlete-day-timeline" aria-label="Linha do tempo do seu dia esportivo">
    <div class="athlete-day-timeline-head"><div><span class="eyebrow">SEU DIA ESPORTIVO</span><h3>Onde você está agora</h3></div><small>Check-in → treino → recuperação</small></div>
    <div class="athlete-day-steps">
      <button type="button" class="athlete-day-step ${checkState}" id="athleteTimelineCheckin"><span class="athlete-day-dot">${readiness?'✓':'1'}</span><span><small>Check-in</small><b>${readiness?`${readiness.score}/100 registrado`:'Fazer agora'}</b></span></button>
      <button type="button" class="athlete-day-step ${workoutState}" id="athleteTimelineWorkout"><span class="athlete-day-dot">${sessionToday?'✓':'2'}</span><span><small>Treino</small><b>${esc(workoutText)}</b></span></button>
      <button type="button" class="athlete-day-step ${recoveryState}" id="athleteTimelineRecovery"><span class="athlete-day-dot">${responseReady?'✓':'3'}</span><span><small>Recuperação</small><b>${esc(recoveryText)}</b></span></button>
    </div>
  </section>`;
}

function hpWeeklyAthleteRhythm(d){
  const plan=d?.planejamentoSemanal;
  const summary=d?.resumoSemanal;
  if((!plan || plan.estado==='SemCiclo') && !summary)return '';
  const completed=Number(summary?.treinosConcluidosSemana ?? plan?.treinosConcluidosSemana ?? 0);
  const goal=Number(summary?.metaTreinosSemana ?? plan?.metaTreinosSemana ?? 0);
  const remaining=plan?.treinosRestantesSemana!=null?Number(plan.treinosRestantesSemana):Math.max(0,goal-completed);
  const state=String(summary?.estado || plan?.estado || 'Executando');
  const tone=state==='Revisar'||state==='Proteger'?'protect':state==='Equilibrada'||state==='Consolidar'?'balanced':'active';
  const label=tone==='protect'?'Proteger recuperação':tone==='balanced'?'Semana consolidada':'Semana em andamento';
  const progress=goal>0?Math.min(100,Math.round((completed/goal)*100)):0;
  const next=remaining<=0?'Meta principal atendida':`${remaining} sessão${remaining===1?'':'ões'} restante${remaining===1?'':'s'}`;
  const message=summary?.resumo || plan?.resumo || 'Use a semana como contexto, sem substituir o plano definido pelo profissional.';
  return `<section class="weekly-athlete-rhythm ${tone}" aria-label="Ritmo esportivo da semana">
    <div class="weekly-athlete-rhythm-head"><div><span class="eyebrow">RITMO DA SEMANA</span><h3>${esc(label)}</h3></div><span class="weekly-rhythm-state">${esc(state)}</span></div>
    <div class="weekly-rhythm-progress"><div><strong>${goal>0?`${completed}/${goal}`:`${completed}`}</strong><span>${goal>0?'treinos da meta':'treinos registrados'}</span></div><div class="weekly-rhythm-track"><i style="width:${progress}%"></i></div><b>${esc(next)}</b></div>
    <p>${esc(message)}</p>
    <button type="button" class="weekly-rhythm-details" id="weeklyRhythmDetails">Ver contexto da semana <span>→</span></button>
  </section>`;
}


function hpAthleteLevelSystem(d){
  const game=d?.gamificacao||{};
  const game2=d?.gamificacao2||{};
  const level=Math.max(1,Number(game.nivel||1));
  const xpLevel=Math.max(0,Number(game.xpNoNivel||0));
  const xpNext=Math.max(1,Number(game.xpProximoNivel||500));
  const pct=Math.min(100,Math.round((xpLevel/xpNext)*100));
  const consistency=Math.max(0,Math.min(100,Number(game.consistenciaScore||0)));
  const streak=Math.max(0,Number(game.streakDias||0));
  const stages=[
    {min:1,max:4,name:'Fundação',text:'Construa uma rotina que você consiga repetir.'},
    {min:5,max:9,name:'Ritmo',text:'Regularidade começa a valer mais do que intensidade isolada.'},
    {min:10,max:14,name:'Consistente',text:'Seu histórico já mostra uma base de autocuidado confiável.'},
    {min:15,max:19,name:'Performance sustentável',text:'Evoluir agora significa equilibrar estímulo, recuperação e adesão.'},
    {min:20,max:999,name:'Referência',text:'Seu nível reconhece constância de longo prazo, não excesso de carga.'}
  ];
  const stage=stages.find(x=>level>=x.min&&level<=x.max)||stages[0];
  const aligned=Number(game2.eventosAlinhadosRecentes||0);
  const excess=Number(game2.eventosExcessoRecentes||0);
  const focus=game2.estado==='PriorizarResposta'?'Recuperar também é progresso':game2.estado==='ConstruirConsistencia'?'Construa sequência, não pressão':'Mantenha o comportamento que está funcionando';
  return `<section class="athlete-level-system" aria-label="Sistema de nível do atleta">
    <div class="athlete-level-system-head"><div><span class="eyebrow">ATHLETE LEVEL SYSTEM</span><h2>Nível ${level} • ${esc(stage.name)}</h2><p>${esc(stage.text)}</p></div><div class="athlete-level-orb"><small>NÍVEL</small><strong>${level}</strong><span>${pct}%</span></div></div>
    <div class="athlete-level-progress"><div class="athlete-level-track" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${pct}"><i style="width:${pct}%"></i></div><div><span>${xpLevel}/${xpNext} XP neste nível</span><strong>${Math.max(0,xpNext-xpLevel)} XP para o nível ${level+1}</strong></div></div>
    <div class="athlete-level-signals"><article><small>CONSISTÊNCIA</small><strong>${consistency}/100</strong><span>base da evolução</span></article><article><small>SEQUÊNCIA</small><strong>${streak} dia${streak===1?'':'s'}</strong><span>autocuidado repetido</span></article><article><small>XP ALINHADO</small><strong>${aligned}</strong><span>eventos recentes</span></article><article><small>EXCESSO</small><strong>${excess}</strong><span>não rende progresso extra</span></article></div>
    <div class="athlete-level-principle"><div><small>FOCO DE PROGRESSÃO</small><strong>${esc(focus)}</strong><span>Treino pesado não vale mais por ser pesado. XP reconhece adesão, adequação à prontidão e recuperação bem executada.</span></div><span class="athlete-level-today">+${Number(game.xpHoje||0)} XP hoje</span></div>
  </section>`;
}

function hpStreakIntelligence(d){
  const game=d?.gamificacao||{};
  const game2=d?.gamificacao2||{};
  const missions=d?.missoesContextuais2||{};
  const weekly=d?.planejamentoSemanal||{};
  const summary=d?.resumoSemanal||{};
  const streak=Math.max(0,Number(game.streakDias||0));
  const active=Math.max(0,Number(game.diasAtivos14||0));
  const consistency=Math.max(0,Math.min(100,Number(game.consistenciaScore||0)));
  const weeklyState=String(summary.estado||weekly.estado||'Executando');
  const protective=weeklyState==='Revisar'||weeklyState==='Proteger'||missions.estado==='SemPressaoHoje'||missions.estado==='RecuperacaoProtegida'||game2.estado==='PriorizarResposta';
  const missionDone=Number(missions.missoesConcluidas||0);
  const missionTotal=Number(missions.totalMissoes||0);
  const quality=Math.max(0,Math.min(100,Math.round(consistency*.65+Math.min(14,active)/14*25+(missionTotal>0?Math.min(1,missionDone/missionTotal)*10:5))));
  const tone=protective?'protected':quality>=80?'strong':quality>=55?'building':'restart';
  const label=protective?'Sequência protegida':tone==='strong'?'Sequência sustentável':tone==='building'?'Sequência em construção':'Retomada inteligente';
  const copy=protective?'Seu contexto pede recuperação. Respeitar o plano preserva a qualidade da sequência sem exigir treino para manter streak.':tone==='strong'?'Sua sequência combina repetição com boa adesão. Continue sem buscar intensidade extra só para manter o número.':tone==='building'?'A sequência está ganhando consistência. Priorize o próximo comportamento útil, não a perfeição.':'O streak é contexto, não dívida. Retome pelo próximo check-in ou ação prevista no plano.';
  const protection=protective?'RECUPERAÇÃO CONTA':streak>=7?'SEM PRESSÃO POR MAIS':streak>0?'CONTINUE REPETÍVEL':'RECOMEÇO SEM PUNIÇÃO';
  return `<section class="streak-intelligence ${tone}" aria-label="Inteligência de sequência">
    <div class="streak-intelligence-head"><div><span class="eyebrow">STREAK INTELLIGENCE</span><h3>${esc(label)}</h3><p>${esc(copy)}</p></div><div class="streak-intelligence-ring" role="img" aria-label="Qualidade da sequência ${quality} de 100"><strong>${quality}</strong><span>/100</span></div></div>
    <div class="streak-intelligence-grid"><article><small>STREAK</small><strong>${streak} dia${streak===1?'':'s'}</strong><span>sequência atual</span></article><article><small>DIAS ATIVOS</small><strong>${active}/14</strong><span>janela recente</span></article><article><small>CONSISTÊNCIA</small><strong>${consistency}/100</strong><span>qualidade da adesão</span></article><article><small>PROTEÇÃO</small><strong>${esc(protection)}</strong><span>sem compensação</span></article></div>
    <div class="streak-intelligence-footer"><span>Streak não é obrigação de treinar. Recuperação planejada não vira falha e excesso não cria mérito extra.</span><button type="button" class="secondary" id="streakIntelligenceDetails">Ver consistência <span>→</span></button></div>
  </section>`;
}

function hpDynamicMissions(d){
  const context=d?.missoesContextuais2||{};
  const focus=d?.focoGamificadoDoDia||{};
  const readiness=d?.prontidaoDiaria||{};
  const strategy=d?.estrategiaDoDia||{};
  const game2=d?.gamificacao2||{};
  const source=Array.isArray(context.missoes)?context.missoes:[];
  const recommendation=String(readiness.recomendacaoTreino||strategy.intensidadeSugerida||'');
  const protectedDay=['Recuperacao','Leve'].includes(recommendation)||['SemPressaoHoje','RecuperacaoProtegida'].includes(String(context.estado||''))||game2.estado==='PriorizarResposta';
  const scoreMission=m=>{
    const text=`${m?.titulo||''} ${m?.estadoContextual||''} ${m?.orientacaoContextual||''}`.toLowerCase();
    let score=m?.concluido?-40:30;
    if(protectedDay && /(recuper|sono|hidrata|dor|check|mobilidade|leve)/.test(text))score+=45;
    if(!protectedDay && /(treino|movimento|execu|check|hidrata)/.test(text))score+=25;
    if(String(focus.missaoCodigo||'') && String(m?.codigo||'')===String(focus.missaoCodigo))score+=60;
    return score;
  };
  const ranked=[...source].sort((a,b)=>scoreMission(b)-scoreMission(a)).slice(0,3);
  const primary=ranked[0];
  const done=source.filter(x=>x.concluido).length;
  const total=source.length||Number(context.totalMissoes||0);
  const mode=protectedDay?'Missões adaptadas à recuperação':done===total&&total>0?'Semana consolidada':'Missões dinâmicas do momento';
  const guidance=protectedDay?'Hoje o sistema prioriza comportamentos que protegem recuperação e adesão. Nenhuma missão exige treino para manter progresso.':'A prioridade muda conforme seus registros, prontidão e progresso semanal — não pela busca de intensidade.';
  return `<section class="dynamic-missions ${protectedDay?'protected':'active'}" aria-label="Missões dinâmicas">
    <div class="dynamic-missions-head"><div><span class="eyebrow">DYNAMIC MISSIONS</span><h3>${esc(mode)}</h3><p>${esc(guidance)}</p></div><span class="dynamic-missions-score">${done}/${total||0}</span></div>
    ${primary?`<article class="dynamic-mission-primary"><small>PRÓXIMA MISSÃO ÚTIL</small><strong>${primary.concluido?'✓ ':''}${esc(primary.titulo||focus.missaoTitulo||'Próxima ação')}</strong><p>${esc(primary.orientacaoContextual||focus.orientacao||'Siga o próximo comportamento alinhado ao seu contexto.')}</p>${primary.meta!=null?`<span>${Math.min(Number(primary.progresso||0),Number(primary.meta||0))}/${Number(primary.meta||0)}${primary.recompensaXp?` • +${Number(primary.recompensaXp)} XP`:''}</span>`:''}</article>`:`<article class="dynamic-mission-primary done"><small>SEM PRESSÃO EXTRA</small><strong>Nenhuma missão pendente agora</strong><p>Seu próximo passo pode ser apenas manter os registros e seguir o plano definido.</p></article>`}
    ${ranked.length>1?`<div class="dynamic-missions-list">${ranked.slice(1).map((m,i)=>`<div><span>${i+2}</span><p><strong>${m.concluido?'✓ ':''}${esc(m.titulo||'Missão')}</strong><small>${esc(m.estadoContextual||'contextual')}</small></p></div>`).join('')}</div>`:''}
    <div class="dynamic-missions-footer"><span>Missões se adaptam ao contexto; não substituem o plano profissional e excesso não gera mérito extra.</span><button type="button" class="secondary" id="dynamicMissionsDetails">Ver todas as missões <span>→</span></button></div>
  </section>`;
}

function hpWeeklyChallenges(d){
  const game=d?.gamificacao||{};
  const readiness=d?.prontidaoDiaria||{};
  const context=d?.missoesContextuais2||{};
  const weekly=d?.planejamentoSemanal||{};
  const summary=d?.resumoSemanal||{};
  const challenges=Array.isArray(game.desafiosSemana)?game.desafiosSemana:[];
  const recommendation=String(readiness.recomendacaoTreino||'');
  const protectedWeek=['Recuperacao','Leve'].includes(recommendation)||['SemPressaoHoje','RecuperacaoProtegida'].includes(String(context.estado||''))||['Revisar','Proteger'].includes(String(summary.estado||weekly.estado||''));
  const done=challenges.filter(x=>x.concluido).length;
  const total=challenges.length;
  const progress=total?Math.round(challenges.reduce((acc,x)=>acc+Math.min(1,Number(x.progresso||0)/Math.max(1,Number(x.meta||1))),0)/total*100):0;
  const theme=protectedWeek?'Proteção e recuperação':Number(game.consistenciaScore||0)>=80?'Consistência sustentável':'Construção da semana';
  const headline=protectedWeek?'Seu desafio é proteger a semana':done===total&&total>0?'Desafio semanal consolidado':'Uma semana boa é feita de ações repetíveis';
  const guidance=protectedWeek?'Recuperação planejada, check-ins e hábitos básicos contam. Não há missão de compensar carga perdida.':'O desafio semanal valoriza adesão útil. Não é necessário aumentar intensidade para completar a semana.';
  const ranked=[...challenges].sort((a,b)=>Number(a.concluido)-Number(b.concluido)||((Number(b.progresso||0)/Math.max(1,Number(b.meta||1)))-(Number(a.progresso||0)/Math.max(1,Number(a.meta||1))))).slice(0,3);
  return `<section class="weekly-challenges-intelligent ${protectedWeek?'protected':'active'}" aria-label="Desafio semanal contextual">
    <div class="weekly-challenges-intelligent-head"><div><span class="eyebrow">WEEKLY CHALLENGES</span><h3>${esc(headline)}</h3><p>${esc(guidance)}</p></div><div class="weekly-challenges-progress" role="img" aria-label="Progresso semanal ${progress} por cento"><strong>${progress}%</strong><span>${done}/${total||0}</span></div></div>
    <div class="weekly-challenges-theme"><small>FOCO DA SEMANA</small><strong>${esc(theme)}</strong><span>${protectedWeek?'Manter o plano de recuperação também é cumprir o desafio.':'Complete o que está alinhado ao seu contexto; excesso não rende progresso extra.'}</span></div>
    ${ranked.length?`<div class="weekly-challenges-steps">${ranked.map((x,i)=>{const pct=Math.min(100,Math.round((Number(x.progresso||0)/Math.max(1,Number(x.meta||1)))*100));return `<article class="${x.concluido?'done':''}"><span>${x.concluido?'✓':i+1}</span><div><strong>${esc(x.titulo||'Desafio')}</strong><small>${Math.min(Number(x.progresso||0),Number(x.meta||0))}/${Number(x.meta||0)} • ${pct}%${x.recompensaXp?` • +${Number(x.recompensaXp)} XP`:''}</small><div><i style="width:${pct}%"></i></div></div></article>`}).join('')}</div>`:`<div class="weekly-challenges-empty"><strong>Sem desafio obrigatório agora</strong><span>Continue registrando o dia; o sistema não cria pressão artificial apenas para manter engajamento.</span></div>`}
    <div class="weekly-challenges-intelligent-footer"><span>Desafios semanais não substituem o plano profissional e nunca pedem compensação de treino perdido.</span><button type="button" class="secondary" id="weeklyChallengesDetails">Ver semana completa <span>→</span></button></div>
  </section>`;
}


function hpSeasonalProgress(d){
  const cycle=d?.cicloEsportivoAtual||{};
  if(!cycle?.nome)return '';
  const game=d?.gamificacao||{};
  const summary=d?.resumoSemanal||{};
  const evolution=d?.evolucaoEsportiva||{};
  const week=Math.max(1,Number(cycle.semanaAtual||1));
  const total=Math.max(week,Number(cycle.totalSemanas||week));
  const pct=Math.max(0,Math.min(100,Number(cycle.progressoTemporalPercentual??Math.round((week/total)*100))));
  const workouts=Math.max(0,Number(cycle.treinosNoCiclo||0));
  const readiness=cycle.mediaProntidao!=null?Number(cycle.mediaProntidao):null;
  const consistency=Math.max(0,Math.min(100,Number(game.consistenciaScore||0)));
  const weeklyState=String(summary.estado||'Em andamento');
  const chapter=pct>=90?'Fechamento do ciclo':pct>=65?'Consolidação':pct>=35?'Construção':'Fundação';
  const narrative=pct>=90?'Hora de revisar o ciclo inteiro e reconhecer o que foi sustentável antes de definir o próximo bloco.':pct>=65?'Você já tem base suficiente para observar padrões de consistência, resposta e recuperação ao longo do ciclo.':pct>=35?'O ciclo está ganhando forma. Priorize repetibilidade e resposta do corpo antes de perseguir mais carga.':'O início do ciclo serve para construir base, rotina e referências — não para acelerar resultados.';
  const safety=weeklyState==='Revisar'||weeklyState==='Proteger'?'A semana pede proteção. Isso não interrompe a temporada: recuperação bem executada faz parte do progresso sazonal.':'Progresso sazonal valoriza continuidade do plano, não picos isolados de intensidade.';
  const evoItems=Array.isArray(evolution.itens)?evolution.itens:[];
  const positive=evoItems.filter(x=>/melhor|evolu|est[aá]vel|consisten|adequad|nova/i.test(`${x?.titulo||''} ${x?.resumo||''} ${x?.status||''}`)).length;
  return `<section class="seasonal-progress" aria-label="Progresso sazonal">
    <div class="seasonal-progress-head"><div><span class="eyebrow">SEASONAL PROGRESS</span><h3>${esc(chapter)} • Semana ${week}/${total}</h3><p>${esc(narrative)}</p></div><div class="seasonal-progress-orb" role="img" aria-label="Progresso do ciclo ${Math.round(pct)} por cento"><strong>${Math.round(pct)}%</strong><span>do ciclo</span></div></div>
    <div class="seasonal-progress-track" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(pct)}"><i style="width:${pct}%"></i></div>
    <div class="seasonal-progress-grid"><article><small>CICLO</small><strong>${esc(cycle.nome||'Ciclo atual')}</strong><span>${esc(cycle.perfilEsportivo||'esportivo')}</span></article><article><small>TREINOS</small><strong>${workouts}</strong><span>no ciclo</span></article><article><small>PRONTIDÃO MÉDIA</small><strong>${readiness!=null?num(readiness,1):'—'}</strong><span>resposta acumulada</span></article><article><small>CONSISTÊNCIA</small><strong>${consistency}/100</strong><span>${positive?`${positive} sinais positivos`:'qualidade da adesão'}</span></article></div>
    <div class="seasonal-progress-footer"><div><small>OBJETIVO DO CICLO</small><strong>${esc(cycle.objetivo||'Manter evolução sustentável dentro do plano.')}</strong></div><p>${esc(safety)}</p></div>
  </section>`;
}

function hpAchievementFamilies(d){
  const game=d?.gamificacao||{};
  const achievements=Array.isArray(game.conquistasRecentes)?game.conquistasRecentes:[];
  const families=[
    {key:'consistencia',icon:'🔥',title:'Consistência',hint:'sequência, presença e adesão repetível',rx:/(consist|streak|sequ[eê]ncia|dias|rotina|presen[cç]a|ader[eê]ncia)/i},
    {key:'recuperacao',icon:'♻',title:'Recuperação',hint:'respeito aos sinais e recuperação bem executada',rx:/(recuper|descans|sono|dor|deload|retom|prote[cç])/i},
    {key:'execucao',icon:'✓',title:'Execução',hint:'ações concluídas conforme o plano',rx:/(treino|execu|sess[aã]o|miss[aã]o|meta|plano|check.?in)/i},
    {key:'evolucao',icon:'↗',title:'Evolução',hint:'marcas, progressão e melhora longitudinal',rx:/(progress|evolu|record|pr\b|marca|nível|nivel|xp|performance)/i},
    {key:'habitos',icon:'◎',title:'Hábitos',hint:'hidratação, alimentação e autocuidado diário',rx:/(hidrata|[aá]gua|aliment|nutri|peso|h[aá]bito|di[aá]rio)/i}
  ];
  const grouped=Object.fromEntries(families.map(f=>[f.key,[]]));
  achievements.forEach(a=>{
    const text=`${a?.titulo||''} ${a?.descricao||''}`;
    const family=families.find(f=>f.rx.test(text))||families[2];
    grouped[family.key].push(a);
  });
  const earned=families.filter(f=>grouped[f.key].length>0).length;
  const dominant=[...families].sort((a,b)=>grouped[b.key].length-grouped[a.key].length)[0];
  const dominantCount=dominant?grouped[dominant.key].length:0;
  const headline=achievements.length?(dominantCount>0?`${dominant.title} está aparecendo mais no seu repertório`:'Suas conquistas estão formando um repertório'):'Seu repertório começa com comportamentos repetíveis';
  return `<section class="achievement-families" aria-label="Famílias de conquistas">
    <div class="achievement-families-head"><div><span class="eyebrow">ACHIEVEMENT FAMILIES</span><h3>${esc(headline)}</h3><p>Conquistas agora são agrupadas pelo comportamento que representam. O objetivo é reconhecer qualidade de adesão, não acumular badges sem contexto.</p></div><span class="achievement-family-total">${achievements.length}<small>recentes</small></span></div>
    <div class="achievement-family-grid">${families.map(f=>{const items=grouped[f.key];return `<article class="achievement-family-card ${items.length?'earned':'empty'}"><div class="achievement-family-icon">${f.icon}</div><div><small>${items.length?`${items.length} conquista${items.length===1?'':'s'}`:'em construção'}</small><strong>${esc(f.title)}</strong><span>${esc(f.hint)}</span>${items.length?`<div class="achievement-family-chips">${items.slice(0,3).map(x=>`<span title="${esc(x.descricao||'')}">${esc(x.icone||'◆')} ${esc(x.titulo||'Conquista')}</span>`).join('')}</div>`:''}</div></article>`}).join('')}</div>
    <div class="achievement-families-footer"><span><b>${earned}/5 famílias</b> com conquistas recentes</span><p>Recuperação planejada, constância e hábitos podem ser tão relevantes quanto performance. Intensidade extra não cria uma família “melhor”.</p></div>
  </section>`;
}

function hpAthleteProgressStory(d){
  const evo=d?.evolucaoEsportiva||{};
  const items=Array.isArray(evo.itens)?evo.itens:[];
  if(!items.length)return '';
  const favorable=items.filter(x=>x.estado==='Favoravel');
  const attention=items.filter(x=>x.estado==='Atencao');
  const stable=items.filter(x=>x.estado==='Estavel');
  const highlights=[...favorable,...stable,...attention].slice(0,3);
  const state=String(evo.estado||'Estavel');
  const tone=state==='Evoluindo'?'growing':state==='Observar'?'observe':'steady';
  const chapter=state==='Evoluindo'?'Seu momento mostra evolução em mais de uma frente':state==='Observar'?'Sua evolução continua, com sinais que merecem contexto':'Sua base está sendo construída com consistência';
  const next=attention[0]?.titulo?`Observe ${String(attention[0].titulo).toLowerCase()} sem mudar o plano por conta própria.`:favorable[0]?.titulo?`Continue consolidando ${String(favorable[0].titulo).toLowerCase()} com a mesma regularidade.`:'Continue registrando para deixar sua história cada vez mais confiável.';
  return `<section class="athlete-progress-story ${tone}" aria-label="História da sua evolução">
    <div class="athlete-progress-story-head"><div><span class="eyebrow">SUA HISTÓRIA DE EVOLUÇÃO</span><h2>${esc(chapter)}</h2><p>${esc(evo.resumo||'Seus registros começam a formar uma leitura longitudinal do seu ciclo.')}</p></div><span class="progress-story-state">${esc(state)}</span></div>
    <div class="progress-story-path">${highlights.map((x,i)=>`<article><span class="progress-story-index">${i+1}</span><div><small>${esc(x.categoria||'Evolução')}</small><strong>${esc(x.titulo||'Indicador')}</strong><b>${esc(x.valor||'—')}</b><p>${esc(x.detalhe||x.tendencia||x.mensagem||'')}</p></div></article>`).join('')}</div>
    <div class="progress-story-footer"><div><small>PRÓXIMO CAPÍTULO</small><strong>${esc(next)}</strong><span>Esta narrativa resume tendências registradas e não substitui a interpretação profissional.</span></div><button type="button" class="secondary progress-story-action" id="athleteProgressStoryAction">Ver evolução completa <span>→</span></button></div>
  </section>`;
}

function hpWeeklyReview(d){
  const plan=d?.planejamentoSemanal||{};
  const summary=d?.resumoSemanal||{};
  const trend=d?.tendenciaSemanal||{};
  const game=d?.gamificacao||{};
  const load=d?.cargaIndividualizada||{};
  if((!d?.planejamentoSemanal || plan.estado==='SemCiclo') && !d?.resumoSemanal && !d?.tendenciaSemanal)return '';
  const completed=Number(summary.treinosConcluidosSemana ?? plan.treinosConcluidosSemana ?? 0);
  const goal=Number(summary.metaTreinosSemana ?? plan.metaTreinosSemana ?? 0);
  const adherence=goal>0?Math.min(100,Math.round((completed/goal)*100)):null;
  const consistency=Number(game.consistenciaScore||0);
  const weeklyState=String(summary.estado||plan.estado||'Executando');
  const protectedWeek=weeklyState==='Revisar'||weeklyState==='Proteger';
  const stableWeek=weeklyState==='Equilibrada'||weeklyState==='Consolidar';
  const tone=protectedWeek?'protect':stableWeek?'steady':'active';
  const loadLabel=load.posicaoHistorica||load.estado||'Sem comparação de carga';
  const trendLabel=trend.resumo||summary.resumo||plan.resumo||'Use a semana como contexto para decidir o próximo passo.';
  const challenges=(game.desafiosSemana||[]);
  const challengesDone=challenges.filter(x=>x.concluido).length;
  const nextFocus=protectedWeek?'Recuperação e retorno gradual':stableWeek?'Consolidar o que funcionou':completed<goal?'Retomar pelo próximo treino do plano':'Manter consistência sem buscar carga extra';
  return `<section class="weekly-review ${tone}" aria-label="Revisão da semana esportiva">
    <div class="weekly-review-head"><div><span class="eyebrow">WEEKLY REVIEW</span><h2>${protectedWeek?'Proteja a próxima semana':stableWeek?'Semana consolidada':'Feche a semana com contexto'}</h2><p>${esc(trendLabel)}</p></div><span class="weekly-review-state">${esc(weeklyState)}</span></div>
    <div class="weekly-review-grid">
      <article><small>TREINOS</small><strong>${goal>0?`${completed}/${goal}`:`${completed}`}</strong><span>${adherence!=null?`${adherence}% da meta`:'registrados na semana'}</span></article>
      <article><small>CONSISTÊNCIA</small><strong>${consistency}/100</strong><span>${game.streakDias||0} dia${Number(game.streakDias||0)===1?'':'s'} de sequência</span></article>
      <article><small>MISSÕES</small><strong>${challenges.length?`${challengesDone}/${challenges.length}`:'—'}</strong><span>${challenges.length?'concluídas':'sem missões ativas'}</span></article>
      <article><small>CARGA</small><strong>${load.cargaAtual7!=null?num(load.cargaAtual7,0):'—'}</strong><span>${esc(loadLabel)}</span></article>
    </div>
    <div class="weekly-review-next"><div><small>FOCO DA PRÓXIMA SEMANA</small><strong>${esc(nextFocus)}</strong><span>Use esta síntese como contexto; o plano profissional continua sendo a referência.</span></div><button type="button" class="secondary weekly-review-action" id="weeklyReviewAction">Revisar semana completa <span>→</span></button></div>
  </section>`;
}

function hpTrainingLoadSnapshot(d){
  const load=d?.cargaIndividualizada;
  if(!load || load.cargaAtual7==null)return '';
  const current=Number(load.cargaAtual7||0);
  const median=load.medianaCargaHistorica!=null?Number(load.medianaCargaHistorica):null;
  const state=String(load.estado||'');
  const tone=state==='RevisarContexto'?'review':state==='ObservarContexto'?'observe':'steady';
  const label=tone==='review'?'Revisar contexto':tone==='observe'?'Observar carga':'Dentro do contexto';
  const comparison=load.posicaoHistorica||'Comparação com sua referência pessoal';
  const message=load.leitura||load.resumo||'A carga recente deve ser interpretada junto de recuperação, dor e prontidão.';
  const scale=median&&median>0?Math.min(100,Math.round((current/median)*50)):50;
  return `<section class="training-load-snapshot ${tone}" aria-label="Resumo da carga de treino recente">
    <div class="training-load-snapshot-head"><div><span class="eyebrow">CARGA RECENTE</span><h3>Seu esforço no contexto pessoal</h3></div><span class="training-load-state">${esc(label)}</span></div>
    <div class="training-load-numbers"><div><strong>${num(current,0)}</strong><span>carga • 7 dias</span></div><div><strong>${median!=null?num(median,0):'—'}</strong><span>mediana pessoal</span></div></div>
    <div class="training-load-reference" aria-label="Comparação visual com referência pessoal"><span>recente</span><div><i style="width:${scale}%"></i><b></b></div><span>referência</span></div>
    <p><strong>${esc(comparison)}</strong><br>${esc(message)}</p>
    <button type="button" class="training-load-details" id="trainingLoadSnapshotDetails">Ver leitura completa <span>→</span></button>
  </section>`;
}

function hpBodyContextBrief(d,readiness){
  const plan=d?.planejamentoSemanal||{};
  const summary=d?.resumoSemanal||{};
  const load=d?.cargaIndividualizada||{};
  const response=d?.respostaSessao||{};
  const weeklyState=String(summary.estado||plan.estado||'Executando');
  const loadState=String(load.estado||'');
  const responseState=String(response.estado||'');
  const protectedWeek=weeklyState==='Revisar'||weeklyState==='Proteger';
  const reviewLoad=loadState==='RevisarContexto';
  const observeLoad=loadState==='ObservarContexto';
  const reviewRecovery=responseState==='Revisar';
  const observeRecovery=responseState==='Observar';
  const tone=(protectedWeek||reviewLoad||reviewRecovery)?'review':(observeLoad||observeRecovery)?'observe':'steady';
  const title=tone==='review'?'Hoje pede contexto':tone==='observe'?'Vale observar a resposta':'Contexto estável';
  const weekText=protectedWeek?'semana protegida':weeklyState==='Equilibrada'||weeklyState==='Consolidar'?'semana consolidada':'semana em andamento';
  const loadText=reviewLoad?'carga pede revisão':observeLoad?'carga para observar':'carga no contexto';
  const recoveryText=reviewRecovery?'recuperação pede revisão':observeRecovery?'recuperação para observar':response.sessaoNome?'recuperação estável':readiness?'check-in registrado':'check-in pendente';
  const action=!readiness?'Faça o check-in para completar a leitura do dia.':tone==='review'?'Use os detalhes abaixo antes de decidir como conduzir a próxima sessão.':tone==='observe'?'Acompanhe os sinais do dia sem transformar o insight em prescrição.':'Siga o plano do dia e use os insights como contexto.';
  return `<div class="body-context-brief ${tone}" aria-label="Resumo rápido do contexto esportivo"><div class="body-context-icon" aria-hidden="true">${tone==='review'?'!':tone==='observe'?'~':'✓'}</div><div><span class="eyebrow">LEITURA RÁPIDA</span><h3>${esc(title)}</h3><p>${esc(weekText)} • ${esc(loadText)} • ${esc(recoveryText)}</p><small>${esc(action)}</small></div></div>`;
}

function hpDailyClosureCard(execution){
  const x=execution||{};
  const total=Number(x.concluidos||0)+Number(x.pendentes||0);
  if(!total && !x.diaFechado)return '';
  const pct=Math.max(0,Math.min(100,Number(x.progressoPercentual||0)));
  const closed=!!x.diaFechado;
  const tone=closed?'closed':pct>=75?'almost':'open';
  const title=closed?'Dia fechado':pct>=75?'Quase lá':'Feche o dia no seu ritmo';
  const copy=closed
    ? `Você registrou como o dia terminou${x.percepcaoDoDia!=null?` • percepção ${x.percepcaoDoDia}/10`:''}.`
    : `${x.concluidos||0} concluído${Number(x.concluidos||0)===1?'':'s'} • ${x.pendentes||0} pendente${Number(x.pendentes||0)===1?'':'s'}. Não precisa buscar perfeição.`;
  return `<section class="daily-closure-card ${tone}" aria-label="Fechamento do dia esportivo">
    <div class="daily-closure-main"><div><span class="eyebrow">FECHAMENTO DO DIA</span><h3>${esc(title)}</h3><p>${esc(copy)}</p></div><strong>${closed?'✓':`${num(pct,0)}%`}</strong></div>
    <div class="daily-closure-track" aria-hidden="true"><i style="width:${closed?100:pct}%"></i></div>
    <button type="button" class="daily-closure-action" id="dailyClosureAction">${closed?'Revisar fechamento':'Fechar meu dia'} <span>→</span></button>
  </section>`;
}

function hpEndOfDayFlow(d){
  const execution=d?.execucaoDoDia||{};
  const hydration=d?.hidratacaoContextual||{};
  const readiness=d?.prontidaoDiaria;
  const response=d?.respostaSessao||{};
  const closed=!!execution.diaFechado;
  const completed=Number(execution.concluidos||0),pending=Number(execution.pendentes||0),total=completed+pending;
  const progress=Math.max(0,Math.min(100,Number(execution.progressoPercentual||0)));
  const hydrationPct=hydration.progressoPercentual!=null?Math.max(0,Math.min(100,Number(hydration.progressoPercentual))):null;
  const trained=!!response.sessaoNome;
  const status=closed?'closed':progress>=75?'ready':'open';
  const title=closed?'Seu dia ficou registrado':progress>=75?'Seu dia está pronto para fechar':'Antes de encerrar, faça uma leitura rápida';
  const copy=closed
    ?`Percepção final ${execution.percepcaoDoDia??'—'}/10${execution.resumoFechamento?` • ${execution.resumoFechamento}`:''}`
    :'Fechar o dia consolida o que aconteceu sem exigir perfeição nem criar metas extras.';
  const workoutText=trained?`${response.sessaoNome}${response.rpeSessao!=null?` • RPE ${response.rpeSessao}/10`:''}`:'Sem sessão registrada hoje';
  const hydrationText=hydrationPct!=null?`${num(hydrationPct,0)}% da meta`:(hydration.consumidoMl!=null?`${num(hydration.consumidoMl,0)} ml registrados`:'Sem registro de água');
  const bodyText=readiness?`${readiness.score}/100 • ${readiness.recomendacaoTreino==='Recuperacao'?'Recuperação':readiness.recomendacaoTreino}`:'Check-in não registrado';
  return `<section class="end-of-day-flow ${status}" aria-label="End-of-Day Flow">
    <div class="end-of-day-flow-head"><div><span class="eyebrow">END-OF-DAY FLOW</span><h2>${esc(title)}</h2><p>${esc(copy)}</p></div><span class="end-of-day-flow-state">${closed?'Fechado':progress>=75?'Pronto':'Em aberto'}</span></div>
    <div class="end-of-day-flow-review">
      <article><small>CORPO</small><strong>${esc(bodyText)}</strong><span>Contexto da manhã preservado até o fechamento.</span></article>
      <article><small>SESSÃO</small><strong>${esc(workoutText)}</strong><span>Treino e esforço entram no histórico quando registrados.</span></article>
      <article><small>HIDRATAÇÃO</small><strong>${esc(hydrationText)}</strong><span>Use o realizado de hoje; não compense volume no fim do dia.</span></article>
      <article><small>ROTEIRO</small><strong>${total?`${completed}/${total} essenciais`:'Sem itens essenciais'}</strong><span>${closed?'Fechamento concluído.':`${num(progress,0)}% acompanhado hoje.`}</span></article>
    </div>
    <div class="end-of-day-flow-footer"><div><small>${closed?'O fechamento pode ser atualizado se você precisar corrigir sua percepção.':'Percepção final + uma nota curta são suficientes para consolidar o dia.'}</small></div><button type="button" class="${closed?'secondary':'primary'} end-of-day-flow-action" id="endOfDayFlowAction">${closed?'Revisar fechamento':'Encerrar meu dia'}</button></div>
    <small class="end-of-day-flow-safety">Fechar o dia registra contexto; não cria obrigação de completar pendências nem de compensar treino, alimentação ou hidratação.</small>
  </section>`;
}

function hpConsistencyCompass(d,readiness){
  const game=d?.gamificacao||{};
  const missions=d?.missoesContextuais2||{};
  const weekly=d?.planejamentoSemanal||{};
  const summary=d?.resumoSemanal||{};
  const score=Number(game.consistenciaScore||0);
  const streak=Number(game.streakDias||0);
  const active=Number(game.diasAtivos14||0);
  const weeklyState=String(summary.estado||weekly.estado||'Executando');
  const protectedDay=weeklyState==='Revisar'||weeklyState==='Proteger'||missions.estado==='SemPressaoHoje'||missions.estado==='RecuperacaoProtegida';
  const completed=Number(missions.missoesConcluidas||0);
  const total=Number(missions.totalMissoes||0);
  const progress=total>0?Math.min(100,Math.round(completed/total*100)):Math.min(100,score);
  const tone=protectedDay?'protected':score>=75?'steady':score>=45?'building':'restart';
  const title=protectedDay?'Consistência também é recuperar':tone==='steady'?'Rotina bem sustentada':tone==='building'?'Consistência em construção':'Retome pelo próximo passo';
  const copy=protectedDay?'Hoje não há pressão para avançar. Respeitar recuperação e retorno gradual faz parte do plano.':tone==='steady'?'Você vem repetindo comportamentos úteis. Continue seguindo o plano sem buscar intensidade extra.':tone==='building'?'Priorize a próxima ação do dia e deixe a sequência crescer com regularidade.':'Comece pequeno: check-in, plano do dia e um registro útil já recolocam a rotina em movimento.';
  return `<section class="consistency-compass ${tone}" aria-label="Bússola de consistência esportiva">
    <div class="consistency-compass-head"><div><span class="eyebrow">CONSISTÊNCIA</span><h3>${esc(title)}</h3></div><span class="consistency-score">${score}/100</span></div>
    <div class="consistency-compass-metrics"><span><small>Sequência</small><b>${streak} dia${streak===1?'':'s'}</b></span><span><small>Dias ativos</small><b>${active}/14</b></span><span><small>Missões</small><b>${total>0?`${completed}/${total}`:'contextuais'}</b></span></div>
    <div class="consistency-compass-track" aria-label="Progresso de consistência"><i style="width:${progress}%"></i></div>
    <p>${esc(copy)}</p>
    <button type="button" class="consistency-compass-action" id="consistencyCompassDetails">Ver progresso e missões <span>→</span></button>
  </section>`;
}

function hpMobileInsightRail(d,readiness){
  const weekly=hpWeeklyAthleteRhythm(d);
  const load=hpTrainingLoadSnapshot(d);
  const recovery=hpRecoveryPulseCard(d?.respostaSessao,readiness);
  if(!weekly && !load && !recovery)return '';
  const brief=hpBodyContextBrief(d,readiness);
  return `<section class="mobile-insight-shell" aria-label="Insights esportivos do seu contexto">
    ${brief}
    <div class="mobile-insight-head"><div><span class="eyebrow">INSIGHTS DO CORPO</span><h3>Semana, carga e recuperação</h3></div><small>Deslize para explorar</small></div>
    <div class="mobile-insight-rail">${weekly}${load}${recovery}</div>
  </section>`;
}

function hpRecoveryPulseCard(x,readiness){
  if(!x || !x.sessaoNome)return '';
  const stable=x.estado==='RespostaEstavel';
  const review=x.estado==='Revisar';
  const stateClass=review?'review':stable?'stable':'observe';
  const stateLabel=review?'Revisar recuperação':stable?'Resposta estável':'Observar resposta';
  const recovery=x.recuperacaoResposta!=null?`${x.recuperacaoResposta}/10`:'—';
  const pain=x.dorResposta!=null?`${x.dorResposta}/10`:'—';
  const readinessValue=x.prontidaoResposta!=null?`${x.prontidaoResposta}/100`:(readiness?`${readiness.score}/100`:'pendente');
  return `<section class="recovery-pulse-card ${stateClass}" aria-label="Resposta da última sessão">
    <div class="recovery-pulse-head"><div><span class="eyebrow">RECOVERY PULSE</span><h3>Como seu corpo respondeu</h3><small>${esc(x.sessaoNome)}${x.rpeSessao!=null?` • RPE ${x.rpeSessao}`:''}</small></div><span class="recovery-pulse-state">${esc(stateLabel)}</span></div>
    <div class="recovery-pulse-metrics"><span><small>Prontidão</small><b>${esc(readinessValue)}</b></span><span><small>Recuperação</small><b>${esc(recovery)}</b></span><span><small>Dor</small><b>${esc(pain)}</b></span></div>
    <p>${esc(x.leitura||x.resumo||'Acompanhe sua resposta antes de decidir como conduzir a próxima sessão.')}</p>
    <div class="recovery-pulse-actions"><button class="secondary" id="recoveryPulseDetails">Ver leitura completa</button>${!readiness?'<button class="primary" id="recoveryPulseCheckin">Fazer check-in</button>':''}</div>
  </section>`;
}

