function hpExecutionDayCard(execution){
  const x=execution||{},items=x.itens||[];
  return `<section class="card guided-day-card"><div class="card-head"><div><span class="eyebrow">ROTEIRO DE HOJE</span><h3>Execute o plano, não persiga perfeição</h3></div><strong>${num(x.progressoPercentual||0,0)}%</strong></div>
    <div class="guided-day-track"><i style="width:${Math.min(100,Number(x.progressoPercentual||0))}%"></i></div>
    <div class="guided-day-list">${items.map(i=>`<article class="guided-day-item ${String(i.status||'').toLowerCase()}"><span class="guided-state">${i.status==='Concluido'?'✓':i.status==='Opcional'?'○':'•'}</span><div><strong>${esc(i.titulo)}</strong><small>${esc(i.descricao||'')}</small>${i.meta?`<span>${esc(i.valorAtual||'0')} / ${esc(i.meta)}</span>`:''}</div><b>${i.status==='Opcional'?'opcional':`${num(i.progressoPercentual||0,0)}%`}</b></article>`).join('')}</div>
    <div class="guided-day-footer"><span>${x.concluidos||0} concluídos • ${x.pendentes||0} pendentes</span><button class="${x.diaFechado?'secondary':'primary'}" id="closeAthleteDay">${x.diaFechado?'Atualizar fechamento':'Fechar meu dia'}</button></div>
  </section>`;
}

const HP_EVENING_REFLECTION_V0226='v0.22.6';

function hpEveningChipV0226(name,value,label){
  return `<label class="evening-reflection-chip-v0226">
    <input type="radio" name="${name}" value="${esc(value)}" required>
    <span>${esc(label)}</span>
  </label>`;
}

function hpEveningSummaryV0226(f,current){
  const execucao=val(f,'execucaoPercebida');
  const dificuldade=val(f,'dificuldadePercebida');
  const energia=val(f,'energiaFinal');
  const aprendizado=val(f,'aprendizado');
  const livre=val(f,'resumoLivre');

  const parts=[];
  if(execucao)parts.push(`Execução: ${execucao}`);
  if(dificuldade)parts.push(`Dificuldade: ${dificuldade}`);
  if(energia)parts.push(`Energia final: ${energia}`);
  if(aprendizado)parts.push(`Aprendizado: ${aprendizado}`);
  if(livre)parts.push(`Observação: ${livre}`);

  return parts.join(' • ')||current?.resumoFechamento||null;
}

function hpWireEveningReflectionV0226(){
  const slider=document.querySelector('[name="percepcaoDoDia"]');
  const output=document.querySelector('[data-evening-score-v0226]');
  if(slider&&output){
    const sync=()=>{output.textContent=`${slider.value}/10`;};
    slider.addEventListener('input',sync);
    sync();
  }
}

function openCloseAthleteDay(current){
  const score=current?.percepcaoDoDia??7;

  patientPortalModal('Reflexão do fim do dia',`
    <div class="span-2 evening-reflection-v0226" data-evening-reflection-v0226="${HP_EVENING_REFLECTION_V0226}">
      <div class="evening-reflection-head-v0226">
        <div>
          <span class="eyebrow">EVENING REFLECTION 2.0</span>
          <h3>Feche o dia em menos de 1 minuto.</h3>
          <p>Registre como foi de verdade. O objetivo é aprender com o dia, não dar nota para você.</p>
        </div>
        <div class="evening-reflection-time-v0226"><b>≈45s</b><span>para fechar o dia</span></div>
      </div>

      <label class="evening-reflection-score-v0226">
        <div><span>Como o dia terminou?</span><output data-evening-score-v0226>${score}/10</output></div>
        <input type="range" name="percepcaoDoDia" min="0" max="10" step="1" value="${score}" required>
        <div class="evening-reflection-scale-v0226"><small>Muito difícil</small><small>Muito bom</small></div>
      </label>

      <fieldset class="evening-reflection-group-v0226">
        <legend>Quanto do planejado você conseguiu executar?</legend>
        <div class="evening-reflection-chips-v0226">
          ${hpEveningChipV0226('execucaoPercebida','Quase nada','Quase nada')}
          ${hpEveningChipV0226('execucaoPercebida','Parte do plano','Parte')}
          ${hpEveningChipV0226('execucaoPercebida','Maioria do plano','Maioria')}
          ${hpEveningChipV0226('execucaoPercebida','Tudo que estava previsto','Tudo')}
        </div>
      </fieldset>

      <fieldset class="evening-reflection-group-v0226">
        <legend>Como foi a dificuldade do dia?</legend>
        <div class="evening-reflection-chips-v0226">
          ${hpEveningChipV0226('dificuldadePercebida','Leve','Leve')}
          ${hpEveningChipV0226('dificuldadePercebida','Adequada','Adequada')}
          ${hpEveningChipV0226('dificuldadePercebida','Alta','Alta')}
          ${hpEveningChipV0226('dificuldadePercebida','Muito alta','Muito alta')}
        </div>
      </fieldset>

      <fieldset class="evening-reflection-group-v0226">
        <legend>Como está sua energia agora?</legend>
        <div class="evening-reflection-chips-v0226">
          ${hpEveningChipV0226('energiaFinal','Muito baixa','Muito baixa')}
          ${hpEveningChipV0226('energiaFinal','Baixa','Baixa')}
          ${hpEveningChipV0226('energiaFinal','Boa','Boa')}
          ${hpEveningChipV0226('energiaFinal','Alta','Alta')}
        </div>
      </fieldset>

      <label class="evening-reflection-note-v0226">
        <span>O que o dia te ensinou?</span>
        <textarea name="aprendizado" rows="2" maxlength="240" placeholder="Ex.: treinar mais cedo funcionou melhor; senti fome no meio da tarde; o treino encaixou bem."></textarea>
      </label>

      <label class="evening-reflection-note-v0226">
        <span>Observação opcional</span>
        <textarea name="resumoLivre" rows="2" maxlength="240" placeholder="${esc(current?.resumoFechamento||'Algo que seu profissional deveria saber?')}"></textarea>
      </label>

      <div class="evening-reflection-safety-v0226">
        <b>Sem punição</b>
        <span>Executar menos, sentir dificuldade ou terminar cansado não reduz seu valor nem gera diagnóstico. Esses registros ajudam a entender padrões e ajustar o acompanhamento.</span>
      </div>
    </div>
  `,async f=>{
    await api('/api/portal/me/fechamento-dia',{
      method:'POST',
      body:JSON.stringify({
        percepcaoDoDia:integer(f,'percepcaoDoDia'),
        resumo:hpEveningSummaryV0226(f,current)
      })
    });
  });

  setTimeout(hpWireEveningReflectionV0226,0);
}

function patientScaleField(label,name,value=5){
  const safe=Math.max(0,Math.min(10,Number(value??5)));
  return `<label class="patient-scale-field span-2"><span class="patient-scale-label"><b>${esc(label)}</b><output data-scale-output="${name}">${safe}</output></span><input class="patient-scale-range" type="range" min="0" max="10" step="1" name="${name}" value="${safe}"><span class="patient-scale-legend"><small>0</small><small>10</small></span></label>`;
}

const HP_MORNING_CHECKIN_V0221='v0.22.1';

function hpMorningScaleCopyV0221(key){
  return ({
    sonoQualidade:['Muito ruim','Excelente'],
    energiaNivel:['Sem energia','Energia máxima'],
    dorNivel:['Sem dor','Dor muito intensa'],
    disposicaoNivel:['Sem disposição','Muito disposto'],
    recuperacaoNivel:['Nada recuperado','Totalmente recuperado']
  })[key]||['0','10'];
}

function hpMorningScaleFieldV0221(label,key,value,icon){
  const [low,high]=hpMorningScaleCopyV0221(key);
  const safe=value==null?5:Number(value);
  return `<label class="morning-checkin-field-v0221">
    <div class="morning-checkin-field-head-v0221">
      <span><i>${icon}</i><b>${esc(label)}</b></span>
      <output data-morning-output-v0221="${key}">${safe}/10</output>
    </div>
    <input type="range" name="${key}" min="0" max="10" step="1" value="${safe}" data-morning-range-v0221="${key}" required>
    <div class="morning-checkin-scale-v0221"><small>${esc(low)}</small><small>${esc(high)}</small></div>
  </label>`;
}

function hpWireMorningCheckinV0221(){
  document.querySelectorAll('[data-morning-range-v0221]').forEach(input=>{
    const key=input.dataset.morningRangeV0221;
    const output=document.querySelector(`[data-morning-output-v0221="${key}"]`);
    const sync=()=>{ if(output)output.textContent=`${input.value}/10`; };
    input.addEventListener('input',sync);
    sync();
  });

  const sleep=document.querySelector('[name="sonoHoras"]');
  const sleepOut=document.querySelector('[data-morning-sleep-v0221]');
  if(sleep&&sleepOut){
    const syncSleep=()=>{ sleepOut.textContent=`${Number(sleep.value||0).toFixed(1)} h`; };
    sleep.addEventListener('input',syncSleep);
    syncSleep();
  }
}

function openDailyReadiness(current){
  const value=(key,fallback='')=>current&&current[key]!=null?current[key]:fallback;
  const done=!!current;

  patientPortalModal(done?'Atualizar check-in da manhã':'Check-in da manhã',`
    <div class="span-2 morning-checkin-v0221" data-morning-checkin-v0221="${HP_MORNING_CHECKIN_V0221}">
      <div class="morning-checkin-intro-v0221">
        <div>
          <span class="eyebrow">MORNING CHECK-IN 2.0</span>
          <h3>${done?'Como você está agora?':'Comece o dia ouvindo o corpo.'}</h3>
          <p>Leva cerca de 30 segundos. Responda pelo que está acontecendo hoje — não pelo treino que você gostaria de conseguir fazer.</p>
        </div>
        <div class="morning-checkin-time-v0221"><strong>≈30s</strong><span>5 sinais + sono</span></div>
      </div>

      <div class="morning-checkin-sleep-v0221">
        <div><span>🌙</span><div><b>Horas de sono</b><small>Quanto você dormiu desde ontem?</small></div></div>
        <output data-morning-sleep-v0221>${Number(value('sonoHoras',7.5)).toFixed(1)} h</output>
        <input name="sonoHoras" type="range" min="0" max="16" step="0.1" value="${value('sonoHoras',7.5)}" required>
        <div class="morning-checkin-sleep-scale-v0221"><small>0 h</small><small>8 h</small><small>16 h</small></div>
      </div>

      <div class="morning-checkin-grid-v0221">
        ${hpMorningScaleFieldV0221('Qualidade do sono','sonoQualidade',value('sonoQualidade',7),'☾')}
        ${hpMorningScaleFieldV0221('Energia','energiaNivel',value('energiaNivel',7),'⚡')}
        ${hpMorningScaleFieldV0221('Dor corporal','dorNivel',value('dorNivel',0),'●')}
        ${hpMorningScaleFieldV0221('Disposição','disposicaoNivel',value('disposicaoNivel',7),'↗')}
        ${hpMorningScaleFieldV0221('Recuperação percebida','recuperacaoNivel',value('recuperacaoNivel',7),'♻')}
      </div>

      <div class="morning-checkin-explain-v0221">
        <b>O que acontece com essas respostas?</b>
        <span>Elas contextualizam sua prontidão do dia e ajudam o profissional a entender sono, energia, dor, disposição e recuperação ao longo do tempo.</span>
      </div>

      <div class="morning-checkin-safety-v0221">
        <b>Sem julgamento</b>
        <span>Não existe resposta “boa” para agradar o sistema. Registrar um dia ruim também é informação útil. O AESYN não usa este check-in como diagnóstico.</span>
      </div>
    </div>
  `,async f=>{
    await api('/api/portal/me/prontidao',{method:'POST',body:JSON.stringify({
      data:todayISO(),
      sonoHoras:dec(f,'sonoHoras'),
      sonoQualidade:integer(f,'sonoQualidade'),
      energiaNivel:integer(f,'energiaNivel'),
      dorNivel:integer(f,'dorNivel'),
      disposicaoNivel:integer(f,'disposicaoNivel'),
      recuperacaoNivel:integer(f,'recuperacaoNivel')
    })});
  });

  setTimeout(hpWireMorningCheckinV0221,0);
}

