// ===== v0.17.6 — Nutrition Builder 2.0 =====
const HP_NUTRITION_BUILDER_2='v0.17.6';
const HP_DIET_MEAL_LIBRARY='v0.17.7';
const HP_PATIENT_PREFERENCES_SMART_ADAPTATION='v0.17.8';

function hpNutritionNormalizeSearch(value){
  return String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
}

function hpNutritionFoodOptions(alimentos,selectedId='',term=''){
  const q=hpNutritionNormalizeSearch(term);
  const tokens=q.split(/\s+/).filter(Boolean);
  const selected=(alimentos||[]).find(a=>String(a.id)===String(selectedId));
  let ranked=(alimentos||[]).map(a=>{
    const name=hpNutritionNormalizeSearch(a.nome);
    const category=hpNutritionNormalizeSearch(a.categoria);
    if(tokens.length&&!tokens.every(t=>name.includes(t)||category.includes(t)))return null;
    let score=0;
    if(q){
      if(name===q)score+=1000;
      if(name.startsWith(q))score+=500;
      if(name.includes(q))score+=250;
      if(category.startsWith(q))score+=80;
      for(const t of tokens){if(name.startsWith(t))score+=40;if(name.includes(t))score+=20;if(category.includes(t))score+=5}
    }else{
      if(String(a.categoria||'').startsWith('PT-BR'))score+=100;
    }
    return {a,score};
  }).filter(Boolean);
  ranked.sort((x,y)=>y.score-x.score||String(x.a.nome||'').localeCompare(String(y.a.nome||''),'pt-BR'));
  let visible=ranked.slice(0,q?120:80).map(x=>x.a);
  if(selected&&!visible.some(x=>String(x.id)===String(selected.id)))visible.unshift(selected);
  const hint=q?`${visible.length}${ranked.length>visible.length?` de ${ranked.length}`:''} resultado(s)`:`Digite para buscar • mostrando ${visible.length} de ${(alimentos||[]).length}`;
  return `<option value="">${hint}</option>`+visible.map(a=>`<option value="${a.id}" ${String(a.id)===String(selectedId)?'selected':''}>${esc(a.nome)}${a.categoria?` • ${esc(a.categoria)}`:''}</option>`).join('');
}

function hpNutritionSubRow(alimentos,sub=null){
  return `<div class="substitution-row nutrition-sub-row">
    <select name="subFood">${hpNutritionFoodOptions(alimentos,sub?.alimentoId||sub?.foodId||'')}</select>
    <input name="subQty" type="number" step="0.01" value="${sub?.quantidade??''}" placeholder="Qtd">
    <input name="subUnit" value="${esc(sub?.unidade||'g')}" placeholder="Unid.">
    <input name="subGrams" type="number" step="0.01" value="${sub?.quantidadeGramas??''}" placeholder="Gramas">
    <button type="button" class="remove-sub" aria-label="Remover substituição">×</button>
  </div>`;
}

function hpNutritionItemRow(alimentos,item=null){
  const selected=item?.alimentoId||item?.foodId||'';
  const subs=item?.substituicoes||[];
  const qty=Number(item?.quantidade??100)||100, grams=Number(item?.quantidadeGramas??100)||100;
  const unit=String(item?.unidade||'g');
  const per=qty>0?Math.round((grams/qty)*100)/100:(hpDefaultGramsPerMeasure(unit)||1);
  return `<div class="meal-item-builder nutrition-item-builder2" data-meal-portion-manager="v0.19.12">
    <div class="nutrition-food-search"><input name="foodSearch" type="search" autocomplete="off" placeholder="Buscar alimento: arroz, frango, banana, iogurte..."><small class="nutrition-search-hint">Busca inteligente por nome e categoria • catálogo grande otimizado</small></div>
    <div class="meal-item-main meal-portion-main">
      <select name="foodId">${hpNutritionFoodOptions(alimentos,selected)}</select>
      <input name="qty" type="number" step="0.01" min="0" value="${qty}" placeholder="Qtd">
      <select name="unit" aria-label="Forma de medida">${hpFoodMeasureOptions(unit)}</select>
      <input name="gramsPerUnit" type="number" step="0.01" min="0.01" value="${per}" placeholder="g/medida" title="Quantos gramas existem em uma medida">
      <input name="grams" type="number" step="0.01" min="0" value="${grams}" placeholder="Gramas">
      <button type="button" class="secondary duplicate-nutrition-item">Duplicar alimento</button>
      <button type="button" class="secondary smart-food-equivalents">Alternativas equivalentes</button>
      <button type="button" class="secondary add-sub">+ Substituição</button>
      <button type="button" class="remove-builder-row" aria-label="Remover alimento">×</button>
    </div>
    <div class="food-measure-hint">${unit==='g'?`${num(grams,0)} g`:`${num(qty,2)} ${esc(unit)} • ${num(per,1)} g/medida`} • ajuste qualquer campo e o AESYN recalcula</div>
    <div class="portion-quick-tools"><span>Porção rápida</span><button type="button" data-portion-factor="0.75">¾×</button><button type="button" data-portion-factor="0.9">−10%</button><button type="button" data-portion-factor="1.1">+10%</button><button type="button" data-portion-factor="1.25">1¼×</button></div>
    <div class="item-macro-preview">Selecione um alimento para calcular os macros.</div>
    <div class="smart-food-equivalence-panel hidden" data-smart-food-equivalence="v0.19.13"></div>
    <div class="substitution-list">${subs.map(x=>hpNutritionSubRow(alimentos,x)).join('')}</div>
  </div>`;
}

function hpNutritionMealBuilder(alimentos,meal=null,index=1){
  const items=meal?.itens?.length?meal.itens:[null];
  const time=meal?.horario?String(meal.horario).slice(0,5):(index===1?'08:00':'12:00');
  return `<section class="meal-builder nutrition-meal-builder2" data-meal-index="${index}" data-meal-id="${esc(meal?.id||'')}" data-meal-manager="v0.19.12">
    <div class="meal-builder-head">
      <div class="meal-meta"><input name="mealName" placeholder="Nome da refeição" value="${esc(meal?.nome||(index===1?'Café da manhã':'Refeição '+index))}"><input name="mealTime" type="time" value="${time}"></div>
      <div class="nutrition-meal-actions"><button type="button" class="ghost move-meal-up" title="Mover para cima">↑</button><button type="button" class="ghost move-meal-down" title="Mover para baixo">↓</button><button type="button" class="secondary duplicate-nutrition-meal">Duplicar refeição</button><button type="button" class="secondary save-meal-template" ${meal?.id?'':'disabled'} title="Disponível após salvar o plano">Salvar refeição</button><button type="button" class="remove-meal secondary">Remover</button></div>
    </div>
    <div class="meal-target-builder"><small>META DESTA REFEIÇÃO • OPCIONAL</small><div>
      <input name="mealMetaCalorias" type="number" min="1" step="1" placeholder="kcal" value="${meal?.metas?.calorias??meal?.metaCalorias??''}">
      <input name="mealMetaProteinasG" type="number" min="0" step="0.1" placeholder="Proteína g" value="${meal?.metas?.proteinasG??meal?.metaProteinasG??''}">
      <input name="mealMetaCarboidratosG" type="number" min="0" step="0.1" placeholder="Carbo g" value="${meal?.metas?.carboidratosG??meal?.metaCarboidratosG??''}">
      <input name="mealMetaGordurasG" type="number" min="0" step="0.1" placeholder="Gordura g" value="${meal?.metas?.gordurasG??meal?.metaGordurasG??''}">
      <input name="mealMetaFibrasG" type="number" min="0" step="0.1" placeholder="Fibra g" value="${meal?.metas?.fibrasG??meal?.metaFibrasG??''}">
    </div></div>
    <div class="meal-items">${items.map(x=>hpNutritionItemRow(alimentos,x)).join('')}</div>
    <div class="nutrition-meal-footer">
      <div class="meal-scale-tools"><button type="button" class="ghost add-meal-item">+ Adicionar alimento</button><span>Escalar porções:</span><button type="button" data-meal-scale="0.8">80%</button><button type="button" data-meal-scale="1.1">+10%</button><button type="button" data-meal-scale="1.2">120%</button></div>
      <div class="nutrition-meal-live-total" aria-live="polite"><strong>0 kcal</strong><span>P 0g • C 0g • G 0g • Fibra 0g</span></div>
    </div>
  </section>`;
}

function hpNutritionBuilderRefreshItem(row,alimentos){
  const select=row.querySelector('[name=foodId]');
  const grams=Number(row.querySelector('[name=grams]')?.value||0);
  const a=(alimentos||[]).find(x=>String(x.id)===String(select?.value));
  const preview=row.querySelector('.item-macro-preview');
  if(!preview)return;
  if(!a){preview.textContent='Selecione um alimento para calcular os macros.';return}
  const f=grams/100;
  preview.textContent=`${num(Number(a.caloriasPor100g||0)*f,0)} kcal • P ${num(Number(a.proteinasPor100g||0)*f)}g • C ${num(Number(a.carboidratosPor100g||0)*f)}g • G ${num(Number(a.gordurasPor100g||0)*f)}g`;
}

const HP_SMART_FOOD_EQUIVALENCES='v0.19.13';
const HP_SMART_EQUIVALENCE_DEFAULT_TOLERANCE=10;
function hpNutritionFoodMacros(food,grams){
  const f=Math.max(0,Number(grams||0))/100;
  return {kcal:Number(food?.caloriasPor100g||0)*f,p:Number(food?.proteinasPor100g||0)*f,c:Number(food?.carboidratosPor100g||0)*f,g:Number(food?.gordurasPor100g||0)*f,fib:Number(food?.fibrasPor100g||0)*f};
}
function hpNutritionEquivalenceScore(target,candidate){
  const rel=(a,b,floor=1)=>Math.abs(a-b)/Math.max(Math.abs(a),floor);
  return (rel(target.kcal,candidate.kcal,50)*0.34)+(rel(target.p,candidate.p,5)*0.31)+(rel(target.c,candidate.c,8)*0.20)+(rel(target.g,candidate.g,4)*0.15);
}
function hpFindSmartFoodEquivalences(alimentos,sourceFood,sourceGrams,tolerance=HP_SMART_EQUIVALENCE_DEFAULT_TOLERANCE){
  if(!sourceFood||!(sourceGrams>0))return [];
  const target=hpNutritionFoodMacros(sourceFood,sourceGrams);
  const targetKcal=Math.max(target.kcal,1);
  return (alimentos||[]).filter(x=>String(x.id)!==String(sourceFood.id)&&Number(x.caloriasPor100g||0)>0).map(food=>{
    const grams=Math.max(1,Math.min(600,(targetKcal/Number(food.caloriasPor100g||1))*100));
    const macros=hpNutritionFoodMacros(food,grams);
    let score=hpNutritionEquivalenceScore(target,macros);
    if(sourceFood.categoria&&food.categoria&&String(sourceFood.categoria).toLowerCase()===String(food.categoria).toLowerCase())score*=0.86;
    const kcalDiff=Math.abs(macros.kcal-target.kcal)/Math.max(target.kcal,1)*100;
    return {food,grams,macros,score,kcalDiff};
  }).filter(x=>x.kcalDiff<=Math.max(5,Number(tolerance||10)*1.5)).sort((a,b)=>a.score-b.score).slice(0,6);
}
function hpRenderSmartFoodEquivalences(row,alimentos){
  const panel=row.querySelector('.smart-food-equivalence-panel');if(!panel)return;
  const food=(alimentos||[]).find(x=>String(x.id)===String(row.querySelector('[name=foodId]')?.value));
  const grams=Number(row.querySelector('[name=grams]')?.value||0);
  if(!food||!(grams>0)){panel.classList.remove('hidden');panel.innerHTML='<div class="smart-equivalence-empty">Selecione um alimento e informe a porção para buscar alternativas equivalentes.</div>';return;}
  const target=hpNutritionFoodMacros(food,grams);
  const options=hpFindSmartFoodEquivalences(alimentos,food,grams,HP_SMART_EQUIVALENCE_DEFAULT_TOLERANCE);
  panel.classList.remove('hidden');
  panel.innerHTML=`<div class="smart-equivalence-head"><div><span class="eyebrow">TROCAR SEM SAIR DO PLANO</span><strong>Alternativas próximas de ${esc(food.nome)}</strong><small>Compara calorias e distribuição de macros. Revise antes de aplicar ao plano.</small></div><button type="button" class="ghost close-smart-equivalence">Fechar</button></div><div class="smart-equivalence-target"><span>${num(target.kcal,0)} kcal</span><span>P ${num(target.p)}g</span><span>C ${num(target.c)}g</span><span>G ${num(target.g)}g</span></div><div class="smart-equivalence-grid">${options.length?options.map((x,i)=>`<article class="smart-equivalence-card"><div><strong>${esc(x.food.nome)}</strong><small>${esc(x.food.categoria||'Alternativa nutricional')}</small></div><b>${num(x.grams,0)} g</b><div class="smart-equivalence-macros"><span>${num(x.macros.kcal,0)} kcal</span><span>P ${num(x.macros.p)}g</span><span>C ${num(x.macros.c)}g</span><span>G ${num(x.macros.g)}g</span></div><small>dif. energética ${num(x.kcalDiff,1)}%</small><button type="button" class="secondary apply-smart-equivalence" data-food-id="${x.food.id}" data-grams="${x.grams.toFixed(2)}">Usar esta alternativa</button></article>`).join(''):'<div class="smart-equivalence-empty">Nenhuma alternativa próxima foi encontrada no catálogo atual.</div>'}</div>`;
  panel.querySelector('.close-smart-equivalence')?.addEventListener('click',()=>panel.classList.add('hidden'));
  panel.querySelectorAll('.apply-smart-equivalence').forEach(btn=>btn.addEventListener('click',()=>{
    const select=row.querySelector('[name=foodId]'),unit=row.querySelector('[name=unit]'),per=row.querySelector('[name=gramsPerUnit]'),qty=row.querySelector('[name=qty]'),gramsInput=row.querySelector('[name=grams]');
    select.value=btn.dataset.foodId;unit.value='g';per.value='1';per.readOnly=true;gramsInput.value=String(Math.round(Number(btn.dataset.grams||0)*10)/10);qty.value=gramsInput.value;
    select.dispatchEvent(new Event('change',{bubbles:true}));gramsInput.dispatchEvent(new Event('input',{bubbles:true}));panel.classList.add('hidden');toast('Alternativa aplicada mantendo uma composição próxima. Revise a refeição antes de salvar.');
  }));
}

function hpNutritionBuilderBindItem(row,alimentos,onChange){
  const select=row.querySelector('[name=foodId]');
  const search=row.querySelector('[name=foodSearch]');
  const qty=row.querySelector('[name=qty]'), unit=row.querySelector('[name=unit]'), grams=row.querySelector('[name=grams]'), per=row.querySelector('[name=gramsPerUnit]');
  if(search){
    let timer=null;
    search.oninput=()=>{clearTimeout(timer);timer=setTimeout(()=>{const current=select.value;select.innerHTML=hpNutritionFoodOptions(alimentos,current,search.value);if([...select.options].some(o=>o.value===current))select.value=current;const hint=row.querySelector('.nutrition-search-hint');if(hint)hint.textContent=search.value.trim()?`Resultados filtrados para “${search.value.trim()}”`:`Busca inteligente por nome e categoria • ${(alimentos||[]).length} alimentos disponíveis`;},120)};
  }
  const renderMeasureHint=()=>{const h=row.querySelector('.food-measure-hint');if(!h)return;const factor=Number(per?.value||0);h.textContent=factor>0?`${num(Number(qty?.value||0),2)} ${unit?.value||'g'} × ${num(factor,1)} g = ${num(Number(grams?.value||0),1)} g • ajuste qualquer campo e o AESYN recalcula`:'Informe a equivalência em gramas para esta medida.'};
  const refresh=()=>{hpNutritionBuilderRefreshItem(row,alimentos);renderMeasureHint();onChange?.()};
  const syncFromMeasure=()=>{const q=Number(qty?.value||0),factor=Number(per?.value||0);if(q>=0&&factor>0)grams.value=String(Math.round(q*factor*100)/100);refresh()};
  const syncFromGrams=()=>{const g=Number(grams?.value||0),factor=Number(per?.value||0);if(g>=0&&factor>0)qty.value=String(Math.round((g/factor)*100)/100);refresh()};
  select.onchange=refresh;
  if(unit)unit.onchange=()=>{const d=hpDefaultGramsPerMeasure(unit.value);if(d!=null){per.value=String(d);per.readOnly=true}else{per.readOnly=false;if(!(Number(per.value)>0))per.value=''}syncFromMeasure()};
  if(qty)qty.oninput=syncFromMeasure;if(per)per.oninput=syncFromMeasure;if(grams)grams.oninput=syncFromGrams;
  row.querySelectorAll('[data-portion-factor]').forEach(b=>b.onclick=()=>{const factor=Number(b.dataset.portionFactor||1);const current=Number(grams?.value||0);if(current>0){grams.value=String(Math.round(current*factor*10)/10);syncFromGrams()}});
  row.querySelector('.remove-builder-row').onclick=()=>{const list=row.parentElement;if(list.children.length>1){row.remove();onChange?.()}};
  row.querySelector('.add-sub').onclick=()=>{const list=row.querySelector('.substitution-list');list.insertAdjacentHTML('beforeend',hpNutritionSubRow(alimentos));const sub=list.lastElementChild;sub.querySelector('.remove-sub').onclick=()=>sub.remove()};
  row.querySelectorAll('.remove-sub').forEach(b=>b.onclick=()=>b.closest('.substitution-row')?.remove());
  row.querySelector('.smart-food-equivalents')?.addEventListener('click',()=>hpRenderSmartFoodEquivalences(row,alimentos));
  row.querySelector('.duplicate-nutrition-item').onclick=()=>{const clone=row.cloneNode(true);row.after(clone);delete clone.dataset.hpBound;hpNutritionBuilderBindItem(clone,alimentos,onChange);hpNutritionBuilderRefreshItem(clone,alimentos);onChange?.()};
  const d=hpDefaultGramsPerMeasure(unit?.value);if(per&&d!=null){per.readOnly=true;if(!(Number(per.value)>0))per.value=String(d)}
  refresh();
}

function hpNutritionBuilderBindMeal(meal,alimentos,onChange){
  const items=meal.querySelector('.meal-items');
  const bindAll=()=>items.querySelectorAll('.nutrition-item-builder2').forEach(r=>{if(r.dataset.hpBound)return;r.dataset.hpBound='1';hpNutritionBuilderBindItem(r,alimentos,onChange)});
  bindAll();
  meal.querySelector('.add-meal-item').onclick=()=>{items.insertAdjacentHTML('beforeend',hpNutritionItemRow(alimentos));bindAll();onChange?.()};
  meal.querySelector('.remove-meal').onclick=()=>{const all=$$('#mealBuilders .nutrition-meal-builder2');if(all.length>1){meal.remove();onChange?.()}};
  meal.querySelector('.duplicate-nutrition-meal').onclick=()=>{
    const clone=meal.cloneNode(true);meal.after(clone);clone.dataset.hpBound='';clone.dataset.mealId='';clone.querySelectorAll('.nutrition-item-builder2').forEach(x=>delete x.dataset.hpBound);const save=clone.querySelector('.save-meal-template');if(save)save.disabled=true;hpNutritionBuilderBindMeal(clone,alimentos,onChange);onChange?.();
  };
  meal.querySelector('.move-meal-up')?.addEventListener('click',()=>{const prev=meal.previousElementSibling;if(prev){meal.parentElement.insertBefore(meal,prev);onChange?.()}});
  meal.querySelector('.move-meal-down')?.addEventListener('click',()=>{const next=meal.nextElementSibling;if(next){meal.parentElement.insertBefore(next,meal);onChange?.()}});
  meal.querySelectorAll('[data-meal-scale]').forEach(btn=>btn.onclick=()=>{const factor=Number(btn.dataset.mealScale||1);meal.querySelectorAll('.nutrition-item-builder2 [name=grams]').forEach(g=>{const value=Number(g.value||0);if(value>0){g.value=String(Math.round(value*factor*10)/10);g.dispatchEvent(new Event('input',{bubbles:true}))}});toast(`Porções da refeição ajustadas para ${Math.round(factor*100)}%.`)});
  meal.querySelector('.save-meal-template')?.addEventListener('click',async()=>{const id=meal.dataset.mealId;if(!id){toast('Salve o plano primeiro para transformar esta refeição em modelo.',true);return}const name=prompt('Nome do modelo de refeição:',meal.querySelector('[name=mealName]')?.value||'Refeição');if(!name)return;try{await api(`/api/refeicoes-plano/${id}/salvar-como-modelo`,{method:'POST',body:JSON.stringify({nome:name.trim(),categoria:'Favoritas',descricao:'Salva pelo Gerenciador de Refeições AESYN.'})});toast('Refeição salva na biblioteca profissional.')}catch(e){toast(e.message||'Não foi possível salvar a refeição.',true)}});
  meal.querySelectorAll('input').forEach(i=>i.addEventListener('input',()=>onChange?.()));
}

function hpNutritionBuilderTotals(alimentos){
  let kcal=0,p=0,c=0,g=0,fib=0;
  $$('#mealBuilders .nutrition-item-builder2').forEach(r=>{
    const a=(alimentos||[]).find(x=>String(x.id)===String(r.querySelector('[name=foodId]')?.value));
    const grams=Number(r.querySelector('[name=grams]')?.value||0);
    if(!a||!grams)return;
    const m=grams/100;
    kcal+=Number(a.caloriasPor100g||0)*m;p+=Number(a.proteinasPor100g||0)*m;c+=Number(a.carboidratosPor100g||0)*m;g+=Number(a.gordurasPor100g||0)*m;fib+=Number(a.fibrasPor100g||0)*m;
  });
  return {kcal,p,c,g,fib};
}

function hpNutritionBuilderMealTotals(meal,alimentos){
  let kcal=0,p=0,c=0,g=0,fib=0;
  meal.querySelectorAll('.nutrition-item-builder2').forEach(r=>{
    const a=(alimentos||[]).find(x=>String(x.id)===String(r.querySelector('[name=foodId]')?.value));
    const grams=Number(r.querySelector('[name=grams]')?.value||0);
    if(!a||!grams)return;
    const m=grams/100;
    kcal+=Number(a.caloriasPor100g||0)*m;
    p+=Number(a.proteinasPor100g||0)*m;
    c+=Number(a.carboidratosPor100g||0)*m;
    g+=Number(a.gordurasPor100g||0)*m;
    fib+=Number(a.fibrasPor100g||0)*m;
  });
  return {kcal,p,c,g,fib};
}

function hpNutritionBuilderUpdatePreview(alimentos){
  const f=$('#nutritionBuilder2Form');if(!f)return;
  const t=hpNutritionBuilderTotals(alimentos);
  $$('#mealBuilders .nutrition-meal-builder2').forEach(meal=>{
    const mt=hpNutritionBuilderMealTotals(meal,alimentos);
    const live=meal.querySelector('.nutrition-meal-live-total');
    if(live)live.innerHTML=`<strong>${num(mt.kcal,0)} kcal</strong><span>P ${num(mt.p)}g • C ${num(mt.c)}g • G ${num(mt.g)}g • Fibra ${num(mt.fib)}g</span>`;
  });
  const macro=$('#nutritionBuilder2MacroPreview');
  if(macro)macro.innerHTML=`<b>${num(t.kcal,0)} kcal</b><span>P ${num(t.p)}g</span><span>C ${num(t.c)}g</span><span>G ${num(t.g)}g</span><span>Fibra ${num(t.fib)}g</span>`;
  const target=$('#nutritionBuilder2TargetDiff');
  if(target){
    const pairs=[['Calorias',t.kcal,Number(val(f,'metaCalorias')||0),'kcal'],['Proteína',t.p,Number(val(f,'metaProteinasG')||0),'g'],['Carboidrato',t.c,Number(val(f,'metaCarboidratosG')||0),'g'],['Gordura',t.g,Number(val(f,'metaGordurasG')||0),'g'],['Fibra',t.fib,Number(val(f,'metaFibrasG')||0),'g']];
    target.innerHTML=pairs.map(([label,current,goal,unit])=>`<div><small>${label}</small><strong>${num(current,label==='Calorias'?0:1)} ${unit}</strong><span>${goal?`meta ${num(goal,label==='Calorias'?0:1)} • ${current-goal>=0?'+':''}${num(current-goal,label==='Calorias'?0:1)} ${unit}`:'sem meta'}</span></div>`).join('');
  }
}

function hpNutritionBuilderRead(form){
  const refeicoes=[...form.querySelectorAll('.nutrition-meal-builder2')].map((m,idx)=>({
    nome:m.querySelector('[name=mealName]').value.trim(),horario:m.querySelector('[name=mealTime]').value||null,ordem:idx+1,observacoes:null,
    metaCalorias:m.querySelector('[name=mealMetaCalorias]').value===''?null:Number(m.querySelector('[name=mealMetaCalorias]').value),
    metaProteinasG:m.querySelector('[name=mealMetaProteinasG]').value===''?null:Number(m.querySelector('[name=mealMetaProteinasG]').value),
    metaCarboidratosG:m.querySelector('[name=mealMetaCarboidratosG]').value===''?null:Number(m.querySelector('[name=mealMetaCarboidratosG]').value),
    metaGordurasG:m.querySelector('[name=mealMetaGordurasG]').value===''?null:Number(m.querySelector('[name=mealMetaGordurasG]').value),
    metaFibrasG:m.querySelector('[name=mealMetaFibrasG]').value===''?null:Number(m.querySelector('[name=mealMetaFibrasG]').value),
    itens:[...m.querySelectorAll('.nutrition-item-builder2')].map(r=>({
      alimentoId:r.querySelector('[name=foodId]').value,quantidade:Number(r.querySelector('[name=qty]').value||0),unidade:r.querySelector('[name=unit]').value.trim(),quantidadeGramas:Number(r.querySelector('[name=grams]').value||0),observacao:null,
      substituicoes:[...r.querySelectorAll('.nutrition-sub-row')].filter(x=>x.querySelector('[name=subFood]').value).map(x=>({alimentoId:x.querySelector('[name=subFood]').value,quantidade:Number(x.querySelector('[name=subQty]').value||0),unidade:x.querySelector('[name=subUnit]').value.trim(),quantidadeGramas:Number(x.querySelector('[name=subGrams]').value||0),observacao:null}))
    })).filter(x=>x.alimentoId)
  }));
  return {nome:val(form,'nome'),dataInicio:val(form,'dataInicio'),dataFim:val(form,'dataFim')||null,status:val(form,'status')||'Ativo',observacoes:val(form,'observacoes')||null,metaCalorias:dec(form,'metaCalorias'),metaProteinasG:dec(form,'metaProteinasG'),metaCarboidratosG:dec(form,'metaCarboidratosG'),metaGordurasG:dec(form,'metaGordurasG'),metaFibrasG:dec(form,'metaFibrasG'),refeicoes};
}


// ===== v0.19.7 — Metabolic Energy Calculator =====
const HP_METABOLIC_ENERGY_CALCULATOR='v0.19.7';
const HP_ACTIVITY_FACTORS={
  sedentario:{label:'Sedentário',factor:1.2,help:'Pouca atividade física estruturada.'},
  leve:{label:'Levemente ativo',factor:1.375,help:'Atividade leve em parte da semana.'},
  moderado:{label:'Moderadamente ativo',factor:1.55,help:'Treinos regulares e rotina ativa.'},
  alto:{label:'Muito ativo',factor:1.725,help:'Treino intenso/frequente ou rotina fisicamente exigente.'},
  extremo:{label:'Extremamente ativo',factor:1.9,help:'Volume muito alto de treinamento e/ou trabalho físico intenso.'}
};
function hpAgeFromBirthDate(value){
  if(!value)return null;
  const born=new Date(`${String(value).slice(0,10)}T12:00:00`);if(Number.isNaN(born.getTime()))return null;
  const now=new Date();let age=now.getFullYear()-born.getFullYear();
  const m=now.getMonth()-born.getMonth();if(m<0||(m===0&&now.getDate()<born.getDate()))age--;
  return age>0?age:null;
}
function hpNormalizeSex(value){
  const s=String(value||'').trim().toLowerCase();
  if(/^m|masc|male|homem/.test(s))return 'masculino';
  if(/^f|fem|female|mulher/.test(s))return 'feminino';
  return '';
}
async function hpLoadMetabolicContext(p){
  const result={patient:p||{},latest:null};
  try{result.patient=await api(`/api/pacientes/${p.id}`)}catch{}
  try{const rows=await api(`/api/pacientes/${p.id}/avaliacoes`);result.latest=Array.isArray(rows)&&rows.length?rows[0]:null}catch{}
  return result;
}
