const HP_MEAL_PORTION_MANAGER_2='v0.19.12';
const HP_DARK_UI_CONSISTENCY='v0.19.11';

// ===== v0.19.14 — Nutrition Calendar =====
const HP_NUTRITION_CALENDAR='v0.19.14';
const hpNutritionCalendarContexts=['Padrao','Treino','Descanso','Viagem','Flexivel'];
function hpCalendarIso(d){const y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0'),day=String(d.getDate()).padStart(2,'0');return `${y}-${m}-${day}`}
function hpCalendarDate(iso){const [y,m,d]=String(iso).split('-').map(Number);return new Date(y,m-1,d)}
function hpCalendarMonthBounds(anchor){const first=new Date(anchor.getFullYear(),anchor.getMonth(),1),last=new Date(anchor.getFullYear(),anchor.getMonth()+1,0);return {first,last}}
function hpCalendarMonthLabel(d){return new Intl.DateTimeFormat('pt-BR',{month:'long',year:'numeric'}).format(d).replace(/^./,x=>x.toUpperCase())}
function hpCalendarContextLabel(value){return ({Padrao:'Padrão',Treino:'Dia de treino',Descanso:'Descanso',Viagem:'Viagem',Flexivel:'Flexível'})[value]||value||'Padrão'}
async function openNutritionCalendar(patient,plans){
  if(!patient?.id)return toast('Paciente não identificado.',true);
  const modal=$('#clinicalActionModal'),box=$('#clinicalActionContent');
  modal.classList.remove('hidden');modal.classList.add('nutrition-modal-open','nutrition-calendar-modal');
  let month=new Date();month=new Date(month.getFullYear(),month.getMonth(),1);
  let selectedIso=hpCalendarIso(new Date());
  let entries=[];
  const getEntry=iso=>entries.find(x=>String(x.data)===iso);
  const load=async()=>{
    const {first,last}=hpCalendarMonthBounds(month);
    entries=await api(`/api/pacientes/${patient.id}/calendario-nutricional?inicio=${hpCalendarIso(first)}&fim=${hpCalendarIso(last)}`);
  };
  const render=async()=>{
    const {first,last}=hpCalendarMonthBounds(month);
    const offset=(first.getDay()+6)%7;
    const total=offset+last.getDate();
    const cells=[];
    for(let i=0;i<Math.ceil(total/7)*7;i++){
      const day=i-offset+1;
      if(day<1||day>last.getDate()){cells.push('<div class="nutrition-calendar-day is-outside"></div>');continue}
      const date=new Date(month.getFullYear(),month.getMonth(),day),iso=hpCalendarIso(date),entry=getEntry(iso),today=iso===hpCalendarIso(new Date());
      cells.push(`<button type="button" class="nutrition-calendar-day ${entry?'has-plan':''} ${today?'is-today':''} ${iso===selectedIso?'is-selected':''}" data-calendar-day="${iso}"><span class="nutrition-calendar-number">${day}</span>${entry?`<strong>${esc(entry.planoNome)}</strong><small>V${entry.planoVersao||1}${entry.metaCalorias?` • ${num(entry.metaCalorias,0)} kcal`:''}</small><em>${esc(hpCalendarContextLabel(entry.contexto))}</em>`:'<span class="nutrition-calendar-empty">Programar</span>'}</button>`)
    }
    const entry=getEntry(selectedIso);
    const planOptions=(plans||[]).map(p=>`<option value="${p.id}" ${String(p.id)===String(entry?.planoAlimentarId)?'selected':''}>${esc(p.nome)} • V${p.versao||1}${p.status?` • ${esc(p.status)}`:''}</option>`).join('');
    const selectedDate=hpCalendarDate(selectedIso);
    const programmed=entries.length,uniquePlans=new Set(entries.map(x=>x.planoAlimentarId)).size;
    box.innerHTML=`<div class="modal-heading"><span class="eyebrow">PLANEJAMENTO NUTRICIONAL</span><h2>Calendário nutricional</h2><p>${esc(patient.nome||'Paciente')} • organize semanas e meses sem recriar os planos alimentares.</p></div>
      <section class="nutrition-calendar-shell" data-nutrition-calendar="v0.19.14">
        <div class="nutrition-calendar-toolbar"><div><button type="button" class="ghost" id="nutritionCalendarPrev">←</button><button type="button" class="ghost" id="nutritionCalendarToday">Hoje</button><button type="button" class="ghost" id="nutritionCalendarNext">→</button></div><div><strong>${esc(hpCalendarMonthLabel(month))}</strong><small>${programmed} dia(s) programado(s) • ${uniquePlans} cardápio(s)</small></div><button type="button" class="secondary" id="nutritionCalendarCopyWeek">Copiar semana →</button></div>
        <div class="nutrition-calendar-weekdays"><span>SEG</span><span>TER</span><span>QUA</span><span>QUI</span><span>SEX</span><span>SÁB</span><span>DOM</span></div>
        <div class="nutrition-calendar-grid">${cells.join('')}</div>
        <div class="nutrition-calendar-editor"><div><span class="eyebrow">${new Intl.DateTimeFormat('pt-BR',{weekday:'long',day:'2-digit',month:'long'}).format(selectedDate).toUpperCase()}</span><h3>${entry?'Editar cardápio do dia':'Programar cardápio do dia'}</h3><p>Troque o plano de um dia sem alterar o restante do mês. O plano original e seu histórico continuam preservados.</p></div>
          <form id="nutritionCalendarDayForm" class="nutrition-calendar-day-form"><label>Cardápio<select name="planId" required><option value="">Selecione um plano...</option>${planOptions}</select></label><label>Contexto<select name="context">${hpNutritionCalendarContexts.map(x=>`<option value="${x}" ${x===(entry?.contexto||'Padrao')?'selected':''}>${hpCalendarContextLabel(x)}</option>`).join('')}</select></label><label class="span-2">Observação<textarea name="notes" rows="2" placeholder="Ex.: almoço fora, treino à noite, viagem...">${esc(entry?.observacoes||'')}</textarea></label><div class="nutrition-calendar-editor-actions"><button type="button" class="ghost" id="nutritionCalendarDelete" ${entry?'':'disabled'}>Limpar dia</button><label class="nutrition-calendar-swap">Trocar com <input id="nutritionCalendarSwapDate" type="date" value=""></label><button type="button" class="secondary" id="nutritionCalendarSwap" ${entry?'':'disabled'}>Trocar dias</button><button type="submit" class="primary">Salvar dia</button></div></form>
        </div>
      </section><div class="form-actions"><button type="button" class="secondary" data-close-clinical-form>Fechar</button></div>`;
    $$('[data-close-clinical-form]').forEach(b=>b.onclick=closeClinicalAction);
    $$('.nutrition-calendar-day[data-calendar-day]').forEach(b=>b.onclick=()=>{selectedIso=b.dataset.calendarDay;render()});
    $('#nutritionCalendarPrev').onclick=async()=>{month=new Date(month.getFullYear(),month.getMonth()-1,1);selectedIso=hpCalendarIso(month);await load();render()};
    $('#nutritionCalendarNext').onclick=async()=>{month=new Date(month.getFullYear(),month.getMonth()+1,1);selectedIso=hpCalendarIso(month);await load();render()};
    $('#nutritionCalendarToday').onclick=async()=>{const t=new Date();month=new Date(t.getFullYear(),t.getMonth(),1);selectedIso=hpCalendarIso(t);await load();render()};
    $('#nutritionCalendarDayForm').onsubmit=async ev=>{ev.preventDefault();const fd=new FormData(ev.currentTarget);await api(`/api/pacientes/${patient.id}/calendario-nutricional/${selectedIso}`,{method:'PUT',body:JSON.stringify({planoAlimentarId:fd.get('planId'),contexto:fd.get('context'),observacoes:fd.get('notes')||null})});toast('Dia programado.');await load();render()};
    $('#nutritionCalendarDelete').onclick=async()=>{if(!entry)return;await api(`/api/pacientes/${patient.id}/calendario-nutricional/${selectedIso}`,{method:'DELETE'});toast('Programação do dia removida.');await load();render()};
    $('#nutritionCalendarCopyWeek').onclick=async()=>{try{await api(`/api/pacientes/${patient.id}/calendario-nutricional/copiar-semana`,{method:'POST',body:JSON.stringify({dataReferencia:selectedIso,sobrescrever:false})});toast('Semana copiada para a próxima.');await load();render()}catch(err){toast(err.message,true)}};
    $('#nutritionCalendarSwap').onclick=async()=>{const other=$('#nutritionCalendarSwapDate').value;if(!entry||!other)return toast('Escolha um segundo dia programado.',true);try{await api(`/api/pacientes/${patient.id}/calendario-nutricional/trocar-dias`,{method:'POST',body:JSON.stringify({dataA:selectedIso,dataB:other})});toast('Dias trocados sem alterar os cardápios.');await load();render()}catch(err){toast(err.message,true)}};
  };
  try{await load();await render()}catch(err){box.innerHTML=`<div class="modal-heading"><span class="eyebrow">PLANEJAMENTO NUTRICIONAL</span><h2>Calendário nutricional</h2></div><div class="empty">${esc(err.message)}</div><div class="form-actions"><button type="button" class="secondary" data-close-clinical-form>Fechar</button></div>`;$$('[data-close-clinical-form]').forEach(b=>b.onclick=closeClinicalAction)}
}

