function enhancePatientMobileFormControls(root=document){
  const scope=root?.querySelectorAll?root:document;
  scope.querySelectorAll('.patient-portal-shell input, .patient-portal-shell textarea, .patient-portal-shell select, .patient-mobile-form input, .patient-mobile-form textarea, .patient-mobile-form select').forEach(control=>{
    if(control.dataset.hpMobileEnhanced==='true')return;
    control.dataset.hpMobileEnhanced='true';
    const type=(control.getAttribute('type')||'').toLowerCase();
    if(type==='number'){
      const step=control.getAttribute('step');
      control.setAttribute('inputmode',step && !['1','1.0'].includes(step)?'decimal':'numeric');
    }
    if(type==='tel')control.setAttribute('inputmode','tel');
    if(type==='email')control.setAttribute('inputmode','email');
    if(type==='url')control.setAttribute('inputmode','url');
    if(control.tagName==='TEXTAREA')control.setAttribute('enterkeyhint','done');
    if(control.required)control.setAttribute('aria-required','true');
  });
}

const hpMobileFormObserver=new MutationObserver(records=>{
  for(const record of records)for(const node of record.addedNodes){if(node.nodeType===1)enhancePatientMobileFormControls(node)}
});
document.addEventListener('DOMContentLoaded',()=>{
  enhancePatientMobileFormControls(document);
  hpMobileFormObserver.observe(document.body,{childList:true,subtree:true});
});
document.addEventListener('focusin',e=>{
  const control=e.target.closest?.('.patient-portal-shell input, .patient-portal-shell textarea, .patient-portal-shell select, .patient-mobile-form input, .patient-mobile-form textarea, .patient-mobile-form select');
  if(!control || window.innerWidth>720)return;
  window.setTimeout(()=>control.scrollIntoView({block:'center',behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'}),120);
});

function enhancePatientFeedbackStates(root=document){
  const scope=root?.querySelectorAll?root:document;
  const selector='.patient-portal-content .empty, .patient-action-sheet .empty';
  const items=[...(scope.matches?.(selector)?[scope]:[]),...scope.querySelectorAll(selector)];
  items.forEach(el=>{
    if(el.dataset.hpFeedbackEnhanced==='true')return;
    el.dataset.hpFeedbackEnhanced='true';
    el.classList.add('patient-empty-state');
    el.setAttribute('role','status');
    el.setAttribute('aria-live','polite');
  });
}
const hpFeedbackObserver=new MutationObserver(records=>{
  for(const record of records)for(const node of record.addedNodes){if(node.nodeType===1)enhancePatientFeedbackStates(node)}
});
document.addEventListener('DOMContentLoaded',()=>{
  enhancePatientFeedbackStates(document);
  hpFeedbackObserver.observe(document.body,{childList:true,subtree:true});
});


function hpMvpChecklistItem(icon,title,text){
  return `<article class="mvp-guide-item"><span>${icon}</span><div><strong>${esc(title)}</strong><small>${esc(text)}</small></div></article>`;
}

function openMvpGuide(){
  const modal=$('#clinicalActionModal'),box=$('#clinicalActionContent');
  if(!modal||!box)return;
  modal.classList.remove('hidden');
  box.innerHTML=`<div class="modal-heading">
      <span class="eyebrow">CENTRAL DE AJUDA AESYN</span>
      <h2>Guia rápido da plataforma</h2>
      <p>Não precisa testar tudo de uma vez. Use este guia para conhecer os principais fluxos da plataforma e localizar rapidamente os recursos do acompanhamento.</p>
    </div>
    <div class="mvp-guide-grid">
      ${hpMvpChecklistItem('01','Acesse o prontuário','Localize o paciente e consulte rapidamente histórico, avaliações e informações relevantes do acompanhamento.')}
      ${hpMvpChecklistItem('02','Registre o atendimento','Documente consulta, avaliação, anamnese e evolução clínica em um fluxo contínuo.')}
      ${hpMvpChecklistItem('03','Prescreva o plano','Organize treino, alimentação, metas, sessões e progressões conforme a estratégia definida para o paciente.')}
      ${hpMvpChecklistItem('04','Acompanhe a evolução','Consulte check-ins, gráficos, alertas, pendências, follow-up e sinais de evolução ao longo do tempo.')}
      ${hpMvpChecklistItem('05','Visualize como paciente','Confira como o plano, os treinos e as informações de saúde aparecem na experiência do paciente.')}
      ${hpMvpChecklistItem('06','Use a Central de Ajuda','Volte a este guia sempre que precisar localizar os principais fluxos da plataforma.')}
    </div>
    <div class="mvp-feedback-card">
      <strong>Precisa registrar uma observação?</strong>
      <p>Use o modelo de suporte para informar a tela, o fluxo e o que aconteceu. Isso facilita a identificação e o acompanhamento da solicitação.</p>
    </div>
    <div class="form-actions"><button class="secondary" type="button" id="copyMvpFeedbackTemplate">Copiar modelo de suporte</button><button class="primary" type="button" data-close-mvp-guide>Fechar ajuda</button></div>`;

  const close=()=>closeClinicalAction();
  $('[data-close-mvp-guide]').onclick=close;
  $('#copyMvpFeedbackTemplate').onclick=async()=>{
    const template=`AESYN Performance

TELA/FLUXO:
O QUE EU ESTAVA FAZENDO:
DESCRIÇÃO:
RESULTADO ESPERADO:
RESULTADO ENCONTRADO:
OBSERVAÇÕES:

PRIORIDADE: baixa / média / alta`;
    try{
      await navigator.clipboard.writeText(template);
      toast('Modelo de suporte copiado.');
    }catch{
      toast('Não foi possível copiar automaticamente.',true);
    }
  };
}

function hpInstallMvpPreviewUi(){
  const guide=$('#mvpGuideButton');
  if(guide)guide.onclick=openMvpGuide;

  document.body.dataset.environment='production';
  

  // Escape fecha a camada mais provável sem alterar dados.
  document.addEventListener('keydown',e=>{
    if(e.key!=='Escape')return;
    const clinical=$('#clinicalActionModal');
    const create=$('#createPatientModal');
    const patient=$('#patientModal');
    const notifications=$('#notificationDrawer');

    if(clinical&&!clinical.classList.contains('hidden')){closeClinicalAction();return}
    if(create&&!create.classList.contains('hidden')){create.classList.add('hidden');return}
    if(patient&&!patient.classList.contains('hidden')){patient.classList.add('hidden');return}
    if(notifications&&!notifications.classList.contains('hidden')){
      notifications.classList.add('hidden');
      return;
    }
    $('.sidebar')?.classList.remove('open');
  });

}

hpInstallMvpPreviewUi();
