// ===== v0.18.16 — Workout Builder Delete + Weekly Patient Plan =====
const HP_WORKOUT_DELETE_WEEKLY_PLAN='v0.18.16';

function hpWorkoutDayToken(value){
  return String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
}

function hpWorkoutTodayAliases(){
  const day=new Date().getDay();
  return [
    ['dom','domingo'],
    ['seg','segunda','segunda-feira'],
    ['ter','terca','terça','terca-feira','terça-feira'],
    ['qua','quarta','quarta-feira'],
    ['qui','quinta','quinta-feira'],
    ['sex','sexta','sexta-feira'],
    ['sab','sábado','sabado']
  ][day].map(hpWorkoutDayToken);
}

function hpWorkoutSessionMatchesToday(session){
  const raw=hpWorkoutDayToken(session?.diasSemana);
  if(!raw||raw.includes('livre'))return false;
  return hpWorkoutTodayAliases().some(alias=>raw.includes(alias));
}

function hpWorkoutTodaySession(plan){
  const sessions=plan?.sessoes||[];
  return sessions.find(hpWorkoutSessionMatchesToday)||sessions[0]||null;
}

function hpPatientWeeklyWorkoutPlan(plan){
  const sessions=plan?.sessoes||[];
  if(!sessions.length)return '';
  const today=hpWorkoutTodaySession(plan);
  return `<section class="patient-weekly-workout-v1816" data-patient-weekly-workout="v0.18.16">
    <div class="patient-weekly-workout-head">
      <div><span class="eyebrow">SEU PLANO COMPLETO</span><h2>Treinos da semana</h2><p>Veja toda a ficha, não só o treino sugerido para hoje.</p></div>
      <span class="weekly-workout-count">${sessions.length} treino(s)</span>
    </div>
    <div class="patient-weekly-workout-grid">
      ${sessions.map((s,index)=>`
        <button type="button" class="patient-weekly-workout-card ${String(s.id)===String(today?.id)?'today':''}" data-week-session="${s.id}">
          <div class="weekly-workout-card-top"><span>Treino ${String.fromCharCode(65+index)}</span>${String(s.id)===String(today?.id)?'<b>HOJE</b>':''}</div>
          <strong>${esc(s.nome||`Treino ${String.fromCharCode(65+index)}`)}</strong>
          <small>${esc(s.diasSemana||'Dias livres')}</small>
          <div><span>${(s.itens||[]).length} exercício(s)</span><i>Ver ficha ›</i></div>
        </button>`).join('')}
    </div>
    <div class="patient-weekly-workout-help"><span>💡</span><p>O destaque “Hoje” serve como atalho. Sua programação completa continua disponível abaixo.</p></div>
  </section>`;
}


// ===== v0.19.18 — Patient ↔ Professional Chat =====
const HP_PATIENT_PROFESSIONAL_CHAT='v0.19.18';
function hpChatContextOptions(selected='Geral'){
  const items=[['Geral','Acompanhamento geral'],['Nutricao','Nutrição'],['Treino','Treino'],['Exames','Exames'],['Medicamentos','Medicamentos e suplementos'],['Recuperacao','Recuperação']];
  return items.map(([v,l])=>`<option value="${v}" ${v===selected?'selected':''}>${l}</option>`).join('');
}
function hpChatMessages(items=[]){
  return items.length?items.map(m=>`<article class="care-chat-message ${m.me?'mine':'theirs'}" data-chat-message="${esc(m.id||'')}"><div class="care-chat-bubble"><div class="care-chat-meta"><span>${esc(m.contextoRotulo||'Acompanhamento')}</span><time>${fmtDateTime(m.dataHoraUtc)}</time></div><p>${esc(m.mensagem||'')}</p></div></article>`).join(''):`<div class="care-chat-empty"><span>✉</span><strong>Conversa aberta</strong><p>Use este espaço para dúvidas sobre treino, nutrição, exames, recuperação e seu acompanhamento.</p></div>`;
}
function hpChatShell(data,{professional=false,patient=null}={}){
  const person=professional?(patient?.nome||data?.paciente?.nome||'Paciente'):(data?.profissional?.nome||'Seu profissional');
  const specialty=!professional&&data?.profissional?.especialidade?` • ${esc(data.profissional.especialidade)}`:'';
  return `<div class="care-chat-shell" data-care-chat="v0.19.18">
    <section class="care-chat-head"><div><span class="eyebrow">AESYN • CONNECTED CARE</span><h2>${professional?'Conversa com '+esc(person):esc(person)}</h2><p>${professional?'Canal contextual para acompanhar dúvidas e adaptações do paciente.':'Tire dúvidas e registre contexto sem esperar a próxima consulta.'}${specialty}</p></div><span class="care-chat-sla">até 24h úteis</span></section>
    <div class="care-chat-safety"><b>Acompanhamento, não emergência.</b><span>${esc(data?.emergencia||'Em situações urgentes, procure atendimento pelos canais adequados.')}</span></div>
    <section class="care-chat-thread" id="careChatThread">${hpChatMessages(data?.mensagens||[])}</section>
    <form class="care-chat-compose" id="careChatForm"><label>Assunto<select name="contexto">${hpChatContextOptions()}</select></label><label class="care-chat-text">Mensagem<textarea name="mensagem" data-hp-draft="chat-message" maxlength="3000" rows="3" required placeholder="Escreva sua dúvida ou observação..."></textarea></label><button class="primary" type="submit">Enviar</button></form>
  </div>`;
}
function hpBindChatForm(url,reload){
  const form=$('#careChatForm'); if(!form)return;
  form.onsubmit=async e=>{e.preventDefault();const b=form.querySelector('button[type=submit]');b.disabled=true;b.textContent='Enviando...';try{await api(url,{method:'POST',body:JSON.stringify({mensagem:val(form,'mensagem'),contexto:val(form,'contexto')}),dedupeKey:`chat-send:${url}`});hpClearDraftV01942(form.querySelector('[name=mensagem]'));form.querySelector('[name=mensagem]').value='';await reload();setTimeout(()=>{const t=$('#careChatThread');if(t)t.scrollTop=t.scrollHeight},30)}catch(err){toast(err.message,true)}finally{b.disabled=false;b.textContent='Enviar'}};
}
async function loadPatientChat(){
  const host=$('#patientPortalContent');
  const data=await api('/api/chat/me');
  host.innerHTML=hpChatShell(data,{professional:false});
  hpBindChatForm('/api/chat/me/mensagens',loadPatientChat);
  setTimeout(()=>{const t=$('#careChatThread');if(t)t.scrollTop=t.scrollHeight},20);
}
async function loadProfessionalPatientChat(patient,host=$('#patientTabContent')){
  const data=await api(`/api/chat/pacientes/${patient.id}`);
  host.innerHTML=hpChatShell(data,{professional:true,patient});
  hpBindChatForm(`/api/chat/pacientes/${patient.id}/mensagens`,()=>loadProfessionalPatientChat(patient,host));
  setTimeout(()=>{const t=$('#careChatThread');if(t)t.scrollTop=t.scrollHeight},20);
}

// ===== v0.19.19 — Deviation & Adherence Events =====
const HP_DEVIATION_ADHERENCE_EVENTS='v0.19.19';
const HP_PROFESSIONAL_ATTENTION_CENTER='v0.19.20';
function hpDeviationPriorityLabel(v){return Number(v)>=3?'Prioridade':Number(v)===2?'Atenção':'Informativo'}
function hpDeviationPriorityClass(v){return Number(v)>=3?'high':Number(v)===2?'medium':'low'}
function hpDeviationAdherenceCard(data){
  const events=data?.eventos||[], recurrent=data?.recorrencias||[];
  return `<section class="card full-card deviation-adherence-card" data-deviation-adherence="v0.19.19">
    <div class="card-head"><div><span class="eyebrow">ADESÃO • ÚLTIMOS ${data?.dias||30} DIAS</span><h3>Execuções diferentes do planejado</h3><small>O AESYN registra padrões para revisão profissional; não altera prescrições automaticamente.</small></div><span class="pill ${Number(data?.prioridadeMaior||0)>=2?'Alta':'Ativa'}">${data?.total||0} evento(s)</span></div>
    <div class="deviation-adherence-stats"><article><strong>${data?.ultimos7Dias||0}</strong><span>últimos 7 dias</span></article><article><strong>${recurrent.length}</strong><span>padrões recorrentes</span></article><article><strong>${(data?.categorias||[]).find(x=>x.categoria==='Nutricao')?.total||0}</strong><span>nutrição</span></article><article><strong>${(data?.categorias||[]).find(x=>x.categoria==='Treino')?.total||0}</strong><span>treino</span></article></div>
    ${recurrent.length?`<div class="deviation-recurrence-list">${recurrent.slice(0,4).map(x=>`<div><span class="deviation-dot ${hpDeviationPriorityClass(x.prioridade)}"></span><strong>${esc(x.categoria)} • ${esc(x.tipo)}</strong><small>${x.total} ocorrência(s) • recorrente</small></div>`).join('')}</div>`:''}
    <div class="deviation-event-list">${events.length?events.slice(0,8).map(x=>`<article><span class="deviation-dot ${hpDeviationPriorityClass(x.prioridade)}"></span><div><strong>${esc(x.titulo)}</strong><small>${fmtDateTime(x.dataHoraUtc)} • ${esc(x.categoria)} • ${hpDeviationPriorityLabel(x.prioridade)}</small><p>${esc(x.detalhe||'')}</p></div></article>`).join(''):'<div class="empty compact">Nenhum desvio relevante registrado neste período.</div>'}</div>
  </section>`;
}
async function hpInjectDeviationAdherence(patientId,host){
  if(!host||host.querySelector('[data-deviation-adherence]'))return;
  try{
    const data=await api(`/api/pacientes/${patientId}/desvios-adesao?dias=30`);
    host.insertAdjacentHTML('beforeend',hpDeviationAdherenceCard(data));
  }catch(err){console.warn('Deviation adherence card unavailable',err)}
}
const __renderPatientTab_v01919=renderPatientTab;
renderPatientTab=function(d){
  __renderPatientTab_v01919(d);
  const host=$('#patientTabContent');
  if(host&&state.patientTab==='resumo'&&state.patientId)hpInjectDeviationAdherence(state.patientId,host);
};


// ===== v0.19.21 — Patient Timeline & Context =====
const HP_PATIENT_TIMELINE_CONTEXT='v0.19.21';
function hpTimelineCategoryLabel(value){
  const v=String(value||'Clinico');
  return ({Clinico:'Clínico',Corpo:'Corpo',Exames:'Exames',Nutricao:'Nutrição',Treino:'Treino',CheckIn:'Check-in',Comunicacao:'Comunicação',Metas:'Metas',Rotina:'Rotina'})[v]||v;
}
function hpTimelineCategoryClass(value){return String(value||'Clinico').toLowerCase().replaceAll('ç','c').replaceAll('ã','a').replaceAll('í','i').replaceAll('ú','u').replaceAll('é','e')}
function hpTimelineIcon(item){
  const c=String(item?.categoria||'Clinico');
  return ({Clinico:'✚',Corpo:'◉',Exames:'⌁',Nutricao:'◫',Treino:'↗',CheckIn:'✓',Comunicacao:'◌',Metas:'◎',Rotina:'•'})[c]||'•';
}
function hpTimelineDayKey(value){const d=new Date(value);return Number.isNaN(d.getTime())?'Sem data':new Intl.DateTimeFormat('pt-BR',{year:'numeric',month:'2-digit',day:'2-digit'}).format(d)}
function hpTimelineDayHeading(value){const d=new Date(value);return Number.isNaN(d.getTime())?'Sem data':new Intl.DateTimeFormat('pt-BR',{weekday:'long',day:'2-digit',month:'long',year:'numeric'}).format(d)}
function hpTimelineCrossContext(items){
  const categories=[...new Set(items.map(x=>hpTimelineCategoryLabel(x.categoria)).filter(Boolean))];
  if(categories.length<2)return '';
  return `<div class="patient-timeline-cross"><span>Contexto cruzado</span><strong>${categories.slice(0,4).map(esc).join(' + ')}</strong><small>Eventos do mesmo dia reunidos para leitura longitudinal, sem inferência clínica automática.</small></div>`;
}
function hpTimelineItem(item){
  const priority=Number(item?.prioridade||0),category=String(item?.categoria||'Clinico');
  const priorityLabel=priority>=3?'Prioridade':priority===2?'Atenção':priority===1?'Informativo':'';
  return `<article class="patient-context-timeline-item ${priority>=2?'needs-attention':''}" data-timeline-category="${esc(category)}">
    <div class="patient-context-timeline-rail"><i class="timeline-domain ${hpTimelineCategoryClass(category)}">${hpTimelineIcon(item)}</i><span></span></div>
    <div class="patient-context-timeline-body">
      <div class="patient-context-timeline-meta"><span class="timeline-category">${esc(hpTimelineCategoryLabel(category))}</span><time>${fmtDateTime(item.dataUtc)}</time>${priorityLabel?`<b class="timeline-priority p${priority}">${priorityLabel}</b>`:''}</div>
      <h4>${esc(item.titulo||String(item.tipo||'Evento').replaceAll('_',' '))}</h4>
      ${item.resumo?`<p>${esc(item.resumo)}</p>`:''}
      <small class="timeline-source">${esc(item.fonte||'AESYN')} • ${esc(String(item.tipo||'evento').replaceAll('_',' '))}</small>
    </div>
  </article>`;
}
function hpRenderPatientContextTimeline(box,timeline,patient){
  const items=[...(timeline||[])].sort((a,b)=>new Date(b.dataUtc)-new Date(a.dataUtc));
  const categories=[...new Set(items.map(x=>String(x.categoria||'Clinico')))];
  const sevenDays=Date.now()-(7*86400000);
  const recent=items.filter(x=>new Date(x.dataUtc).getTime()>=sevenDays).length;
  const attention=items.filter(x=>Number(x.prioridade||0)>=2).length;
  const grouped=new Map();
  items.forEach(x=>{const k=hpTimelineDayKey(x.dataUtc);if(!grouped.has(k))grouped.set(k,[]);grouped.get(k).push(x)});
  box.innerHTML=`<section class="card full-card patient-context-timeline" data-patient-timeline-context="v0.19.21">
    <div class="card-head patient-context-timeline-head"><div><span class="eyebrow">AESYN • CONTEXTO LONGITUDINAL</span><h3>Timeline integrada do paciente</h3><p>Treino, nutrição, check-ins, comunicação, exames e prontuário em uma sequência única para revisão profissional.</p></div><span class="profile-context-badge">${items.length} evento(s)</span></div>
    <div class="patient-context-timeline-stats"><article><strong>${recent}</strong><span>últimos 7 dias</span></article><article><strong>${categories.length}</strong><span>dimensões conectadas</span></article><article><strong>${attention}</strong><span>sinais de atenção</span></article><article><strong>${grouped.size}</strong><span>dias com contexto</span></article></div>
    <div class="patient-context-timeline-filters"><button class="active" data-timeline-filter="Todos">Todos</button>${categories.map(c=>`<button data-timeline-filter="${esc(c)}">${esc(hpTimelineCategoryLabel(c))}</button>`).join('')}</div>
    <div class="patient-context-timeline-days">${items.length?[...grouped.values()].map(dayItems=>`<section class="patient-context-timeline-day" data-timeline-day><div class="patient-context-timeline-date"><strong>${esc(hpTimelineDayHeading(dayItems[0].dataUtc))}</strong><small>${dayItems.length} evento(s)</small></div>${hpTimelineCrossContext(dayItems)}<div>${dayItems.map(hpTimelineItem).join('')}</div></section>`).join(''):sectionEmpty('Ainda não existem eventos suficientes para compor a timeline integrada.')}</div>
    <p class="patient-context-timeline-note">A timeline aproxima fatos registrados no mesmo período para facilitar a revisão. Ela não conclui causalidade, diagnóstico ou necessidade de mudança de conduta.</p>
  </section>`;
  $$('.patient-context-timeline-filters [data-timeline-filter]').forEach(button=>button.onclick=()=>{
    const filter=button.dataset.timelineFilter;
    $$('.patient-context-timeline-filters [data-timeline-filter]').forEach(x=>x.classList.toggle('active',x===button));
    $$('.patient-context-timeline-item').forEach(x=>x.classList.toggle('hidden',filter!=='Todos'&&x.dataset.timelineCategory!==filter));
    $$('[data-timeline-day]').forEach(day=>{const visible=[...day.querySelectorAll('.patient-context-timeline-item')].some(x=>!x.classList.contains('hidden'));day.classList.toggle('hidden',!visible)});
  });
}

// ===== v0.19.22 — Positive Progress / AESYN XP =====
const HP_POSITIVE_PROGRESS_XP='v0.19.22';


// ===== v0.19.23 — Passive Monitoring Foundation =====
const HP_PASSIVE_MONITORING_FOUNDATION='v0.19.23';
function hpPassiveMonitoringMetricValue(m){
  if(m?.total!=null && ['Passos','SonoMinutos','EnergiaAtiva','Distancia','MinutosAtivos'].includes(m.metrica)) return `${num(m.total,1)} ${esc(m.unidade||'')}`;
  if(m?.ultimoValor!=null) return `${num(m.ultimoValor,1)} ${esc(m.unidade||'')}`;
  return '—';
}
function hpPassiveMonitoringCard(data,{professional=false}={}){
  const metrics=data?.metricas||[],sources=(data?.fontes||[]).filter(x=>Number(x.amostras||0)>0);
  return `<section class="card passive-monitoring-card ${professional?'professional':'athlete'}" data-passive-monitoring="v0.19.23">
    <div class="card-head"><div><span class="eyebrow">AESYN • MONITORAMENTO PASSIVO</span><h3>${professional?'Sinais coletados fora do app':'Seus sinais conectados'}</h3><p>Base preparada para Apple Health, Health Connect e Garmin, com leitura longitudinal sem alterar sua conduta automaticamente.</p></div><span class="pill ${data?.totalAmostras?'Ativa':''}">${data?.totalAmostras||0} amostra(s)</span></div>
    <div class="passive-monitoring-sources">${sources.length?sources.map(s=>`<span class="${s.comDadosRecentes?'recent':'stale'}"><i></i><b>${esc(s.rotulo||s.fonte)}</b><small>${s.ultimaSincronizacaoUtc?fmtDateTime(s.ultimaSincronizacaoUtc):'sem sincronização'}</small></span>`).join(''):`<div class="passive-monitoring-empty"><strong>Nenhuma fonte sincronizada ainda</strong><small>A infraestrutura está pronta para receber dados normalizados dos conectores.</small></div>`}</div>
    ${metrics.length?`<div class="passive-monitoring-grid">${metrics.slice(0,7).map(m=>`<article><small>${esc(m.rotulo||m.metrica)}</small><strong>${hpPassiveMonitoringMetricValue(m)}</strong>${m.variacaoPercentual7Dias!=null?`<span>${m.variacaoPercentual7Dias>0?'+':''}${num(m.variacaoPercentual7Dias,1)}% vs. 7 dias anteriores</span>`:'<span>sem comparação semanal</span>'}</article>`).join('')}</div>`:''}
    <p class="passive-monitoring-safety">${esc(data?.mensagemSeguranca||'Dados passivos apoiam a observação longitudinal e não substituem avaliação profissional.')}</p>
  </section>`;
}
async function hpInjectProfessionalPassiveMonitoring(patientId,host){
  if(!host||host.querySelector('[data-passive-monitoring]'))return;
  try{
    const data=await api(`/api/pacientes/${patientId}/monitoramento-passivo?dias=14`);
    const anchor=host.querySelector('.performance-profile-context');
    if(anchor)anchor.insertAdjacentHTML('afterend',hpPassiveMonitoringCard(data,{professional:true}));
    else host.insertAdjacentHTML('afterbegin',hpPassiveMonitoringCard(data,{professional:true}));
  }catch(err){console.warn('Passive monitoring professional summary unavailable',err)}
}
const __renderPatientTab_v01923=renderPatientTab;
renderPatientTab=function(d){
  __renderPatientTab_v01923(d);
  const host=$('#patientTabContent');
  if(host&&state.patientTab==='resumo'&&state.patientId)hpInjectProfessionalPassiveMonitoring(state.patientId,host);
};
const __loadPatientHealth_v01923=loadPatientHealth;
loadPatientHealth=async function(){
  await __loadPatientHealth_v01923();
  const host=$('#patientPortalContent');
  if(!host||host.querySelector('[data-passive-monitoring]'))return;
  try{
    const data=await api('/api/portal/me/monitoramento-passivo?dias=14');
    const anchor=host.querySelector('.patient-health-hero-v0190');
    if(anchor)anchor.insertAdjacentHTML('afterend',hpPassiveMonitoringCard(data,{professional:false}));
  }catch(err){console.warn('Passive monitoring patient summary unavailable',err)}
};

// ===== v0.19.28 — Settings & User Profile =====
(function(){
  function hpProfileAvatar(dataUrl,name){
    const avatar=document.querySelector('#avatar');
    if(!avatar)return;
    if(dataUrl){avatar.style.backgroundImage=`url("${dataUrl}")`;avatar.style.backgroundSize='cover';avatar.style.backgroundPosition='center';avatar.textContent='';avatar.classList.add('has-photo');}
    else{avatar.style.backgroundImage='';avatar.textContent=initials(name||state.user?.nome||'U');avatar.classList.remove('has-photo');}
  }
  function hpCompressProfilePhoto(file){
    return new Promise((resolve,reject)=>{
      if(!file?.type?.startsWith('image/'))return reject(new Error('Selecione uma imagem válida.'));
      const reader=new FileReader();
      reader.onerror=()=>reject(new Error('Não foi possível ler a imagem.'));
      reader.onload=()=>{
        const img=new Image();
        img.onerror=()=>reject(new Error('Imagem inválida.'));
        img.onload=()=>{
          const size=256,canvas=document.createElement('canvas');canvas.width=size;canvas.height=size;
          const ctx=canvas.getContext('2d');
          const scale=Math.max(size/img.width,size/img.height),w=img.width*scale,h=img.height*scale;
          ctx.drawImage(img,(size-w)/2,(size-h)/2,w,h);
          resolve(canvas.toDataURL('image/jpeg',0.82));
        };
        img.src=reader.result;
      };
      reader.readAsDataURL(file);
    });
  }
  async function hpEnhanceAccountSettings(){
    const panel=document.querySelector('#hp-account-panel');
    if(!panel||panel.dataset.v01928)return;
    panel.dataset.v01928='1';
    let account,session;
    try{[account,session]=await Promise.all([api('/api/configuracoes/minha-conta'),api('/api/configuracoes/minha-conta/sessao-atual')]);}catch{return;}
    hpProfileAvatar(account.fotoPerfilDataUrl,account.nome);
    const extra=document.createElement('div');extra.className='profile-settings-v01928';
    extra.innerHTML=`
      <section class="profile-settings-card"><div class="profile-photo-block"><div class="profile-photo-preview">${account.fotoPerfilDataUrl?`<img src="${account.fotoPerfilDataUrl}" alt="Foto de perfil">`:`<span>${esc(initials(account.nome||'U'))}</span>`}</div><div><strong>Foto de perfil</strong><small>Usada apenas na sua experiência de conta. A imagem é reduzida antes do envio.</small><div class="profile-photo-actions"><label class="secondary profile-file-button">Escolher foto<input id="hpProfilePhotoInput" type="file" accept="image/jpeg,image/png,image/webp" hidden></label><button class="ghost" id="hpRemoveProfilePhoto" ${account.fotoPerfilDataUrl?'':'disabled'}>Remover</button></div></div></div></section>
      <section class="profile-settings-card"><div class="card-head"><div><h4>Aparência</h4><small>Preferência sincronizada com sua conta.</small></div></div><div class="profile-theme-choice"><button type="button" data-profile-theme="light" class="${account.temaPreferido==='light'?'active':''}">☀️ Claro</button><button type="button" data-profile-theme="dark" class="${account.temaPreferido==='dark'?'active':''}">🌙 Escuro</button></div></section>
      <section class="profile-settings-card"><div class="card-head"><div><h4>Notificações</h4><small>Escolha quais eventos devem chamar sua atenção.</small></div></div><div class="profile-notification-grid">
        <label><input type="checkbox" data-pref="notificarMensagens" ${account.notificarMensagens?'checked':''}> Mensagens</label>
        <label><input type="checkbox" data-pref="notificarAtualizacoesPlano" ${account.notificarAtualizacoesPlano?'checked':''}> Atualizações do plano</label>
        <label><input type="checkbox" data-pref="notificarLembretes" ${account.notificarLembretes?'checked':''}> Lembretes</label>
        <label><input type="checkbox" data-pref="notificarCheckIns" ${account.notificarCheckIns?'checked':''}> Check-ins</label>
      </div><button class="primary" id="hpSavePreferences">Salvar preferências</button></section>
      <section class="profile-settings-card"><div class="card-head"><div><h4>Privacidade e sessão</h4><small>Informações da sessão atualmente aberta.</small></div></div><div class="account-info-grid"><div><small>IP</small><strong>${esc(session.ip||'—')}</strong></div><div><small>Expira</small><strong>${session.expiraEmUtc?fmtDate(session.expiraEmUtc):'—'}</strong></div><div class="span-2"><small>Dispositivo / navegador</small><strong class="profile-session-agent">${esc(session.userAgent||'Não identificado')}</strong></div></div><p class="form-hint">Por segurança, o logout atual revoga os tokens anteriores da conta. Senhas e conteúdo da foto não são gravados no AuditLog.</p></section>`;
    panel.appendChild(extra);
    extra.querySelector('#hpProfilePhotoInput')?.addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;try{const data=await hpCompressProfilePhoto(file);const r=await api('/api/configuracoes/minha-conta/foto',{method:'PUT',body:JSON.stringify({fotoDataUrl:data})});hpProfileAvatar(r.fotoPerfilDataUrl,account.nome);toast('Foto de perfil atualizada.');window.HealthPlatform?.renderConfiguracoes?.();}catch(err){toast(err.message,true);}});
    extra.querySelector('#hpRemoveProfilePhoto')?.addEventListener('click',async()=>{await api('/api/configuracoes/minha-conta/foto',{method:'PUT',body:JSON.stringify({fotoDataUrl:null})});hpProfileAvatar(null,account.nome);toast('Foto removida.');window.HealthPlatform?.renderConfiguracoes?.();});
    extra.querySelectorAll('[data-profile-theme]').forEach(b=>b.addEventListener('click',()=>{extra.querySelectorAll('[data-profile-theme]').forEach(x=>x.classList.remove('active'));b.classList.add('active');hpApplyTheme(b.dataset.profileTheme);}));
    extra.querySelector('#hpSavePreferences')?.addEventListener('click',async()=>{const theme=extra.querySelector('[data-profile-theme].active')?.dataset.profileTheme||'light';const body={temaPreferido:theme};extra.querySelectorAll('[data-pref]').forEach(x=>body[x.dataset.pref]=x.checked);await api('/api/configuracoes/minha-conta/preferencias',{method:'PUT',body:JSON.stringify(body)});hpApplyTheme(theme);localStorage.setItem(HP_THEME_CHOICE_KEY,'true');toast('Preferências salvas.');});
  }
  const obs=new MutationObserver(()=>{if(document.querySelector('#hp-account-panel'))hpEnhanceAccountSettings();});obs.observe(document.body,{childList:true,subtree:true});
  document.addEventListener('click',e=>{if(e.target.closest('[data-route="configuracoes"]'))setTimeout(hpEnhanceAccountSettings,120);});
  window.HealthPlatform=window.HealthPlatform||{};window.HealthPlatform.enhanceAccountSettings=hpEnhanceAccountSettings;
})();


// ===== v0.19.29 — AESYN App Identity & Theme Completion =====
const HP_APP_IDENTITY_THEME_COMPLETION='v0.19.29';
(function(){
  const standalone=window.matchMedia?.('(display-mode: standalone)').matches||window.navigator.standalone===true;
  document.documentElement.dataset.displayMode=standalone?'standalone':'browser';
  window.addEventListener('load',()=>{
    const splash=document.querySelector('#aesynLaunchScreen');
    if(!splash)return;
    window.setTimeout(()=>splash.classList.add('is-hidden'),standalone?420:0);
  },{once:true});
})();


