function hpMovementSafeMediaUrlV0234(value){
  const raw=String(value||'').trim();
  if(!raw)return null;
  try{
    const u=new URL(raw,window.location.origin);
    return (u.protocol==='http:'||u.protocol==='https:')?u.href:null;
  }catch{return null}
}

