const HP_MOVEMENT_TAXONOMY_FILTERS_V0231='v0.23.1';
const HP_MOVEMENT_SESSION_MODEL_V0232='v0.23.2';
const HP_MOVEMENT_PROGRESSION_REGRESSION_V0233='v0.23.3';
const HP_MOVEMENT_INSTRUCTIONS_MEDIA_V0234='v0.23.4';
const HP_MOVEMENT_COVERAGE_QUALITY_V0235='v0.23.5';
const HP_MOVEMENT_STARTER_PACKS_V0236='v0.23.6';
const HP_PROFESSIONAL_MOVEMENT_LIBRARY_V0237='v0.23.7';
const HP_MOVEMENT_MOBILE_ACCESSIBILITY_V0238='v0.23.8';

function hpMovementFilterOptionsV0231(modalidades){
  const uniq=arr=>[...new Set(arr.filter(Boolean))].sort((a,b)=>a.localeCompare(b,'pt-BR'));
  return {
    modalidades:uniq((modalidades||[]).map(x=>x.nome)),
    objetivos:uniq((modalidades||[]).flatMap(x=>(x.objetivos||[]).map(y=>y.nome))),
    capacidades:uniq((modalidades||[]).flatMap(x=>(x.objetivos||[]).flatMap(y=>(y.capacidades||[]).map(z=>z.nome)))),
    ambientes:uniq((modalidades||[]).flatMap(x=>x.ambientes||[])),
    equipamentos:uniq((modalidades||[]).flatMap(x=>x.equipamentosComuns||[]))
  };
}

function hpMovementQueryV0231(filters){
  const q=new URLSearchParams();
  Object.entries(filters||{}).forEach(([k,v])=>{if(v)q.set(k,v)});
  const s=q.toString();
  return `/api/biblioteca-movimento${s?`?${s}`:''}`;
}

async function openMovementLibraryV0230(){
  const box=$('#clinicalActionContent');
  const modal=$('#clinicalActionModal');
  modal.classList.remove('hidden');
  modal.classList.add('movement-library-modal-v0230','movement-library-modal-v0231');
  box.className='clinical-action-shell movement-library-shell-v0230 movement-library-shell-v0231';
  box.innerHTML=`<div class="modal-heading"><span class="eyebrow">PROFESSIONAL MOVEMENT LIBRARY • v0.23.7</span><h2>Biblioteca de Movimento & Esportes</h2><p>Carregando curadoria, cobertura, sessões e Starter Packs...</p></div>`;

  try{
    const baseData=await api('/api/biblioteca-movimento');
    const options=hpMovementFilterOptionsV0231(baseData.modalidades||[]);
    let current=baseData;

    const render=()=>{
      box.innerHTML=`<div class="modal-heading movement-library-heading-v0230">
        <div>
          <button type="button" class="back-link" id="movementLibraryBackV0230">← Treino & Nutrição</button>
          <span class="eyebrow">AESYN • PROFESSIONAL MOVEMENT LIBRARY 2.0</span>
          <h2>Biblioteca de Movimento & Esportes</h2>
          <p>${esc(current.estrutura||'Modalidade → Objetivo → Capacidade → Sessão → Exercício → Progressão')}</p>
          <button type="button" class="secondary movement-starter-pack-open-v0236" id="movementStarterPacksOpenV0236">Starter Packs</button>
        </div>
        <div class="movement-library-summary-v0230">
          <span><b>${current.totalModalidades||0}</b> modalidades</span>
          <span><b>${current.totalExerciciosAtivos||0}</b> exercícios ativos</span>
          <span><b>${current.totalModelosSessaoAtivos||0}</b> sessões-modelo</span>
        </div>
      </div>

      ${hpProfessionalMovementLibraryNavV0237(current)}

      <div class="movement-library-principle-v0230 movement-library-sources-v0232">
        <div><b>Exercícios</b><span>${esc(current.fonteDosExercicios||'Os exercícios permanecem no catálogo profissional existente.')}</span></div>
        <div><b>Sessões</b><span>${esc(current.fonteDasSessoes||'As sessões reutilizam os modelos existentes do Workout Builder.')}</span></div>
      </div>

      <div id="movementStarterPacksHostV0236" class="movement-starter-packs-host-v0236" hidden></div>

      ${hpMovementCoverageV0235(current.cobertura)}

      <div class="movement-taxonomy-toolbar-v0231" data-movement-taxonomy-filters-v0231="${HP_MOVEMENT_TAXONOMY_FILTERS_V0231}">
        <input id="movementSearchV0230" class="search-input" placeholder="Buscar em tudo que está visível">
        <select id="movementFilterModalityV0231"><option value="">Todas as modalidades</option>${options.modalidades.map(x=>`<option>${esc(x)}</option>`).join('')}</select>
        <select id="movementFilterObjectiveV0231"><option value="">Todos os objetivos</option>${options.objetivos.map(x=>`<option>${esc(x)}</option>`).join('')}</select>
        <select id="movementFilterCapabilityV0231"><option value="">Todas as capacidades</option>${options.capacidades.map(x=>`<option>${esc(x)}</option>`).join('')}</select>
        <select id="movementFilterEnvironmentV0231"><option value="">Todos os ambientes</option>${options.ambientes.map(x=>`<option>${esc(x)}</option>`).join('')}</select>
        <select id="movementFilterEquipmentV0231"><option value="">Todos os equipamentos</option>${options.equipamentos.map(x=>`<option>${esc(x)}</option>`).join('')}</select>
        <button type="button" class="ghost" id="movementClearFiltersV0231">Limpar filtros</button>
      </div>

      <div class="movement-filter-summary-v0231">
        <span><b>${(current.modalidades||[]).length}</b> modalidade(s) visível(is)</span>
        <span>Filtros estruturais no backend + busca textual local</span>
      </div>

      <div id="movementInstructionHostV0234" class="movement-instruction-host-v0234" hidden></div>

      <div id="movementLibraryListV0230" class="movement-library-list-v0230">
        ${(current.modalidades||[]).map(hpMovementModalityV0230).join('')||'<div class="movement-library-no-results-v0231"><b>Nenhuma combinação encontrada.</b><span>Ajuste os filtros; nenhum exercício novo será criado automaticamente.</span></div>'}
      </div>

      <div class="movement-library-safety-v0230 movement-library-safety-v0233">
        <b>Biblioteca não é prescrição</b>
        <span>${esc(current.regraDeSeguranca||'Seleção e progressão dependem do contexto individual e do julgamento profissional.')}</span>
        <small>Progressões/regressões são possibilidades estruturais. Aplicação real deve considerar execução, histórico, objetivo, contexto diário e julgamento profissional.</small>
      </div>`;

      $('#movementLibraryBackV0230').onclick=()=>{closeClinicalAction();navigate('prescricoes')};
      $('#movementStarterPacksOpenV0236').onclick=()=>hpOpenMovementStarterPacksV0236($('#movementStarterPacksHostV0236'));
      hpWireProfessionalMovementLibraryV0237();
      hpMovementApplyAccessibilityV0238();

      $$('[data-movement-quality-open-catalog-v0235]').forEach(btn=>{
        btn.onclick=()=>{closeClinicalAction();openExerciseLibrary2()};
      });

      const search=$('#movementSearchV0230');
      search.oninput=()=>{
        const q=(search.value||'').trim().toLowerCase();
        $$('#movementLibraryListV0230 .movement-modality-v0230').forEach(el=>{
          el.hidden=!!q&&!el.textContent.toLowerCase().includes(q);
        });
      };

      const ids={
        modalidade:'#movementFilterModalityV0231',
        objetivo:'#movementFilterObjectiveV0231',
        capacidade:'#movementFilterCapabilityV0231',
        ambiente:'#movementFilterEnvironmentV0231',
        equipamento:'#movementFilterEquipmentV0231'
      };

      const apply=async()=>{
        const filters={};
        Object.entries(ids).forEach(([key,selector])=>{
          const value=$(selector)?.value||'';
          if(value)filters[key]=value;
        });
        current=await api(hpMovementQueryV0231(filters));
        render();
        Object.entries(ids).forEach(([key,selector])=>{
          if($(selector))$(selector).value=filters[key]||'';
        });
      };

      Object.values(ids).forEach(selector=>{
        if($(selector))$(selector).onchange=apply;
      });

      $('#movementClearFiltersV0231').onclick=()=>{
        current=baseData;
        render();
      };

      $$('[data-movement-exercise-v0230]').forEach(btn=>{
        btn.onclick=async()=>{
          const host=$('#movementInstructionHostV0234');
          if(!host)return;
          host.hidden=false;
          await hpOpenMovementInstructionV0234(btn.dataset.movementExerciseV0230,host);
          host.scrollIntoView({behavior:'smooth',block:'start'});
        };
      });

      $$('[data-movement-session-v0232]').forEach(btn=>{
        btn.onclick=()=>{
          closeClinicalAction();
          openWorkoutLibrary();
        };
      });
    };

    render();
  }catch(err){
    box.innerHTML=`<div class="modal-heading"><span class="eyebrow">SPORTS & MOVEMENT LIBRARY</span><h2>Biblioteca indisponível</h2><p>${esc(err.message||'Não foi possível carregar a estrutura agora.')}</p></div>`;
  }
}

// ===== v0.24.0 — AESYN Explore Foundation =====
const HP_AESYN_EXPLORE_FOUNDATION_V0240='v0.24.0';

function hpExploreContextV0240(x){
  const must=[];
  if(x?.planoAtual)must.push(x.planoAtual);
  if(x?.cicloAtual)must.push(x.cicloAtual);
  if(x?.objetivoAtual)must.push(x.objetivoAtual);

  const want=(Array.isArray(x?.interessesDeclarados)?x.interessesDeclarados:[])
    .map(v=>v?.nome)
    .filter(Boolean);

  const can=[];
  if(x?.frequenciaSemanalRelatada!=null)can.push(`${x.frequenciaSemanalRelatada} dia(s)/semana relatados`);
  return {must,want,can};
}

function hpExploreFoundationV0240(x){
  const ctx=hpExploreContextV0240(x);
  const paths=Array.isArray(x?.caminhos)?x.caminhos:[];
  return `<section class="aesyn-explore-v0240" data-aesyn-explore-v0240="${HP_AESYN_EXPLORE_FOUNDATION_V0240}" aria-labelledby="aesynExploreTitleV0240">
    <div class="aesyn-explore-head-v0240">
      <div>
        <span class="eyebrow">AESYN EXPLORE • FOUNDATION</span>
        <h2 id="aesynExploreTitleV0240">Quero me movimentar. O que faz sentido explorar?</h2>
        <p>Explore separa o que já faz parte do seu plano, o que desperta interesse e o que cabe no contexto real.</p>
      </div>
      <span class="aesyn-explore-badge-v0240">AUTONOMIA GUIADA</span>
    </div>

    <div class="aesyn-explore-compass-v0240">
      <article><span>PRECISO FAZER</span>${ctx.must.length?ctx.must.slice(0,3).map(v=>`<b>${esc(v)}</b>`).join(''):'<p>Seu plano profissional continua sendo a referência quando existir.</p>'}</article>
      <article><span>QUERO FAZER</span>${ctx.want.length?ctx.want.slice(0,3).map(v=>`<b>${esc(v)}</b>`).join(''):'<p>Use Explore para descobrir modalidades e interesses.</p>'}</article>
      <article><span>POSSO FAZER HOJE</span>${ctx.can.length?ctx.can.slice(0,3).map(v=>`<b>${esc(v)}</b>`).join(''):'<p>Tempo, local e recursos serão refinados nas próximas etapas.</p>'}</article>
    </div>

    <div class="aesyn-explore-paths-v0240">
      ${paths.map(p=>`<button type="button" class="aesyn-explore-path-v0240" data-explore-path-v0240="${esc(p.codigo)}">
        <span>${esc(p.tipo||'Explorar')}</span>
        <strong>${esc(p.titulo)}</strong>
        <p>${esc(p.descricao)}</p>
        <div>${(p.modalidades||[]).slice(0,4).map(m=>`<i>${esc(m)}</i>`).join('')}</div>
      </button>`).join('')}
    </div>

    <div id="aesynExploreDetailV0240" class="aesyn-explore-detail-v0240" hidden aria-live="polite"></div>

    <div class="aesyn-explore-safety-v0240">
      <b>Explore não prescreve</b>
      <span>${esc(x?.regraDeAutonomia||'Explore organiza possibilidades sem substituir plano ou orientação profissional.')}</span>
    </div>
  </section>`;
}

function hpWireExploreFoundationV0240(host,data){
  if(!host)return;
  host.querySelectorAll('[data-explore-path-v0240]').forEach(btn=>{
    btn.onclick=()=>{
      const path=(data?.caminhos||[]).find(x=>x.codigo===btn.dataset.explorePathV0240);
      const detail=host.querySelector('#aesynExploreDetailV0240');
      if(!path||!detail)return;
      detail.hidden=false;
      detail.innerHTML=`<div><span class="eyebrow">CAMINHO DE EXPLORAÇÃO</span><h3>${esc(path.titulo)}</h3><p>${esc(path.descricao)}</p></div>
        <div class="aesyn-explore-context-tags-v0240">${(path.contextos||[]).map(x=>`<span>${esc(x)}</span>`).join('')}</div>
        <div class="aesyn-explore-modalities-v0240">${(path.modalidades||[]).map(x=>`<b>${esc(x)}</b>`).join('')}</div>
        <small>Fundação de descoberta: nenhum treino é iniciado, alterado ou publicado automaticamente.</small>`;
      detail.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'nearest'});
    };
  });
}

async function hpInjectExploreFoundationV0240(){
  const portal=$('#patientPortalContent');
  if(!portal||portal.querySelector('[data-aesyn-explore-v0240]'))return;
  try{
    const data=await api('/api/portal/me/explore');
    const home=portal.querySelector('.patient-mobile-home')||portal;
    home.insertAdjacentHTML('beforeend',hpExploreFoundationV0240(data));
    hpWireExploreFoundationV0240(home.querySelector('[data-aesyn-explore-v0240]'),data);
  }catch(e){
    console.warn('AESYN Explore foundation indisponível:',e?.message||e);
  }
}

const __loadMyPatientPortal_v0240=loadMyPatientPortal;
loadMyPatientPortal=async function(){
  await __loadMyPatientPortal_v0240();
  await hpInjectExploreFoundationV0240();
};


